-- Banco de dados do Ponto & Pauta.
-- Tabelas e dados iniciais.

CREATE DATABASE IF NOT EXISTS portal_noticias CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE portal_noticias;
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS posts (
    id INT UNSIGNED NOT NULL AUTO_INCREMENT,
    titulo VARCHAR(180) NOT NULL,
    autor VARCHAR(100) NOT NULL,
    categoria ENUM('Brasil','Mundo','Economia','Tecnologia','Educação','Cultura','Esportes','Famosos','Comunidade') NOT NULL,
    data_publicacao DATE NOT NULL,
    conteudo MEDIUMTEXT NOT NULL,
    imagem_url VARCHAR(2048) NOT NULL DEFAULT '',
    imagem_credito VARCHAR(180) NOT NULL DEFAULT '',
    criado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    atualizado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    INDEX idx_posts_data (data_publicacao, id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


USE portal_noticias;
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS news (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 url_hash CHAR(64) NOT NULL UNIQUE,
 source_key VARCHAR(30) NOT NULL,
 source_name VARCHAR(60) NOT NULL,
 category VARCHAR(40) NOT NULL,
 title VARCHAR(300) NOT NULL,
 summary VARCHAR(600) NOT NULL DEFAULT '',
 content_html MEDIUMTEXT NULL,
 author VARCHAR(180) NOT NULL DEFAULT '',
 license_url VARCHAR(2048) NOT NULL DEFAULT '',
 ai_summary TEXT NULL,
 ai_basis VARCHAR(20) NOT NULL DEFAULT '',
 ai_reference_url VARCHAR(2048) NOT NULL DEFAULT '',
 url VARCHAR(2048) NOT NULL,
 image_url VARCHAR(2048) NOT NULL DEFAULT '',
 published_at DATETIME NOT NULL,
 INDEX idx_news_category_date(category,published_at),
 INDEX idx_news_date(published_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS feed_status (
 source_key VARCHAR(30) PRIMARY KEY,
 last_attempt DATETIME NULL,
 last_success DATETIME NULL,
 status VARCHAR(20) NOT NULL DEFAULT 'pending',
 item_count INT NOT NULL DEFAULT 0,
 message VARCHAR(255) NOT NULL DEFAULT ''
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



