INSERT IGNORE INTO posts (id,titulo,autor,categoria,data_publicacao,conteudo,imagem_url,imagem_credito,criado_em,atualizado_em) VALUES ('1','Da sala de aula para a web: ideias que viram projetos','Gustavo Lacerda','Tecnologia','2026-09-07','Uma página em branco pode ser o começo de uma grande ideia. Neste exemplo fictício, estudantes transformam temas do cotidiano em aplicações para a web, unindo criatividade e programação.\n\nO trabalho começa pelo planejamento: definir os dados necessários, desenhar as telas e organizar as etapas. Depois, PHP, Bootstrap, JavaScript e MySQL dão forma ao projeto.\n\nO portal permite cadastrar, consultar, editar e excluir notícias. Mais do que preencher formulários, a proposta é entender como a informação percorre o navegador, o servidor e o banco de dados.','','','2026-09-07 21:26:50','2026-09-07 21:26:50');
INSERT IGNORE INTO posts (id,titulo,autor,categoria,data_publicacao,conteudo,imagem_url,imagem_credito,criado_em,atualizado_em) VALUES ('2','Biblioteca aberta: um convite para descobrir novas histórias','Redação Ponto & Pauta','Educação','2026-09-06','Neste conteúdo demonstrativo, uma biblioteca escolar organiza encontros de leitura para aproximar os estudantes dos livros.\n\nA ideia é simples: cada participante escolhe uma obra, compartilha suas impressões e escuta outras perspectivas. Contos, romances e quadrinhos dividem espaço na programação.\n\nA iniciativa fictícia mostra como pequenas ações podem estimular a curiosidade e a troca de conhecimento. Este texto é um exemplo para testar a leitura completa de uma notícia no portal.','','','2026-09-07 21:26:50','2026-09-07 21:26:50');
INSERT IGNORE INTO posts (id,titulo,autor,categoria,data_publicacao,conteudo,imagem_url,imagem_credito,criado_em,atualizado_em) VALUES ('3','Arte no bairro: encontros que aproximam a comunidade','Redação Ponto & Pauta','Cultura','2026-09-05','Uma exposição imaginária reúne desenhos, fotografias e relatos sobre a vida no bairro. O conteúdo foi criado apenas para demonstrar o cadastro de notícias de cultura.\n\nCada trabalho apresenta um olhar diferente sobre os mesmos espaços: a praça, as ruas e os lugares de encontro. Visitantes podem conversar sobre as obras e compartilhar suas próprias memórias.\n\nO exemplo ajuda a mostrar a organização dos posts por categoria e a preservação dos parágrafos no conteúdo completo.','','','2026-09-07 21:26:50','2026-09-07 21:26:50');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('1','c4bdfc13f0af840345cbf37d4ac367746bc8211f75b7c098a602e8bf588aab85','g1','g1','Brasil','Justiça derruba suspensão de advogado suspeito de usar IA para influenciar processos na PB','Advogado havia sido suspenso pela OAB-PB, após suspeitade inserir comandos ocultos (\"prompt injection\") em petições apresentadas ao TJPB. Justiça entendeu que a entidade não tem competência legal para aplicar a sanção sem defesa prévia.','https://g1.globo.com/pb/paraiba/noticia/2026/09/07/justica-derruba-suspensao-de-advogado-suspeito-de-usar-ia-para-influenciar-processos-na-pb.ghtml','https://s2-g1.glbimg.com/Q6ic_3rBTGijlmgOBs-G1NwpSLg=/i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2026/B/B/JjRvhqQAGwq8dPXHYLnw/oab.jpg','2026-09-07 21:00:04','','','','A Justiça anulou a suspensão de um advogado investigado por supostamente inserir instruções ocultas em petições. A decisão considerou que a OAB-PB não poderia aplicar a medida sem defesa prévia.','excerpt','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('2','57b44204d120ee61856be5aef31f2b151574fed20b6259420709d777771ca7ac','g1','g1','Brasil','Marconi Perillo promete subsídio no transporte e metrô para o Entorno','Candidato do PSDB participou de culto em Formosa e detalhou propostas para a região. Entre as principais promessas estão o subsídio nas passagens de ônibus, metronização e melhorias na saúde pública.','https://g1.globo.com/go/goias/eleicoes/2026/noticia/2026/09/07/marconi-perillo-promete-subsidio-no-transporte-e-metro-para-o-entorno.ghtml','https://s2-g1.glbimg.com/4BSj5tqVdHHH3B5kIPLh-Qav23A=/i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2026/j/E/1LO3DARviOxF2KPyqyIA/goias-ja2-marconi-0709.jpeg','2026-09-07 20:59:12','','','','Em campanha em Formosa, Marconi Perillo apresentou propostas de subsídio às passagens, transporte por metrô e melhorias na saúde para a região do Entorno.','excerpt','');
