INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('4','b615900b25b798d5d55ffb5e144b6e218d302c5afbbbccf5b8a951f1360b42af','g1','g1','Brasil','VÍDEO mostra avalanche que matou 11 alpinistas em montanha da Rússia','Monte Mizhirgi, onde ocorreu o incidente, fica ao norte da Geórgia, na cordilheira que fica entre o Mar Negro e o Mar Cáspio. Seu pico fica 5.047 metros acima do nível do mar, sendo o','https://g1.globo.com/mundo/noticia/2026/09/07/video-mostra-avalanche-que-matou-11-alpinistas-em-montanha-da-russia.ghtml','https://s2-g1.glbimg.com/FiPQLdGf3vp4LJlOxx00xqXXZmI=/i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2026/V/r/g4ordfSUiXJOOU0HfAdw/captura-de-tela-2026-09-07-173247-1-.jpg','2026-09-07 20:51:27','','','','Uma avalanche no monte Mizhirgi, na Rússia, provocou a morte de 11 alpinistas. A reportagem apresenta imagens do episódio na montanha, localizada na região do Cáucaso.','excerpt','');
