INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('34','02af4b3d881f83319b75ca3e4a6b7e8f4240eea7a9f3c1dc36b63a78f4abe1ce','mundo','g1 · Mundo','Mundo','Kremlin não descarta retomada das negociações de paz com Ucrânia e EUA','Após reuniões de enviados dos EUA com Putin e Zelensky, Moscou mantém aberta a possibilidade de novas negociações de paz, mas diz ser cedo para definir data e local de um novo encontro.','https://g1.globo.com/mundo/noticia/2026/09/07/kremlin-nao-descarta-retomada-das-negociacoes-de-paz-com-ucrania-e-eua.ghtml','https://s2-g1.glbimg.com/Iz8x9k5g_F3ZFJ7x54r58Yr0gWY=/i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2022/J/V/cZKLYBScSPQvaeFy6XsQ/2022-02-24t112457z-1-lynxmpei1n0qc-rtroptp-4-ucrania-crise-kremlin-cortina.jpg','2026-09-07 09:42:05','','','','O Kremlin admitiu a possibilidade de retomar conversas de paz com Ucrânia e Estados Unidos após reuniões diplomáticas. Ainda não há definição de data ou local para outro encontro.','excerpt','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('35','fe3a67d4b2b8934a7ebee9690060e570bc920a3febd158681487e94aa076d97b','mundo','g1 · Mundo','Mundo','Merz amarga revés de proporções catastróficas com vitória da extrema direita na Saxônia-Anhalt','Respaldo contundente de eleitores ao partido radical AfD em estado do Leste alemão traduz erosão da política tradicional e novo fracasso para o chanceler, que se consolida como o líder mais impopular do país','https://g1.globo.com/mundo/blog/sandra-cohen/post/2026/09/07/merz-vitoria-da-afd-saxonia-anhalt.ghtml','https://s2-g1.glbimg.com/p45xzuyECpvU6iLQxxXF-_V_sf8=/i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2026/Q/G/kIwr0aQ5a4xhgTmrAHMA/2026-09-07t121110z-333886968-rc2cenab44us-rtrmadp-3-germany-election-saxony-anhalt-cdu-reaction.jpg','2026-09-07 09:35:08','','','','A análise relaciona a vitória da AfD na Saxônia-Anhalt ao enfraquecimento dos partidos tradicionais e a um novo revés político para o chanceler Friedrich Merz.','excerpt','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('36','f5207c95a1e6440fe98a887ff63070f8e836c4da13602898e547cef7820fc9ee','mundo','g1 · Mundo','Mundo','Nepal tem dia de luto 13 dias após avalanche devastadora','A catástrofe deixou pelo menos 1.398 mortos e mais de 5.500 desaparecidos na fronteira entre Nepal e China, segundo balanços provisórios divulgados nesta segunda-feira (7).','https://g1.globo.com/mundo/noticia/2026/09/07/nepal-tem-dia-de-luto-13-dias-apos-avalanche-devastadora.ghtml','https://s2-g1.glbimg.com/A7AJinoFynwKVcraOoosNGfstwk=/i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2026/0/O/3Yhb3JTpiDC796CEo99w/afp-20260907-c7jv94g-v1-midres-nepaldisasterflood.jpg','2026-09-07 08:59:45','','','','O Nepal realizou um dia de luto após uma avalanche na fronteira com a China. O balanço provisório citado registrava pelo menos 1.398 mortos e mais de 5.500 desaparecidos.','excerpt','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('37','60278bd3e6f8a262b51f01c4bbbdf466ca4bc7fec6f469d7ae650ab09f5035db','mundo','g1 · Mundo','Mundo','O dilema da Europa após direita radical na Alemanha obter vitória estadual inédita desde a 2ª Guerra','Os próximos 12 meses serão marcados por intensa temporada eleitoral em toda a UE; haverá votações em países-chave como França, Itália, Espanha e Polônia. Bruxelas teme que partidos mais \'extremistas\', possam se beneficiar de vitória','https://g1.globo.com/mundo/noticia/2026/09/07/o-dilema-da-europa-apos-direita-radical-na-alemanha-obter-vitoria-estadual-inedita-desde-a-2a-guerra.ghtml','https://s2-g1.glbimg.com/h6Q5dJILczZz_XFq7kOADn4qUYc=/i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2026/m/K/srR9JySMmReQJknAKYsQ/2026-09-06t205139z-2093134816-rc2vdnandkf5-rtrmadp-3-germany-election-saxony-anhalt-afd.jpg','2026-09-07 07:11:50','','','','A vitória estadual da direita radical alemã gera preocupação na União Europeia antes de uma sequência de eleições em países como França, Itália, Espanha e Polônia.','excerpt','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('38','ff2271aaa0508339656255ebee1bb0d8851b253cfad6d5a93128c041cbeaf33c','mundo','g1 · Mundo','Mundo','Trabalhar, dever, trabalhar mais: como crédito caro prende entregadores argentinos aos aplicativos','Fintechs e apps oferecem crédito a quem precisa de dinheiro para despesas como multas e recuperação de motos. Em meio ao avanço do endividamento, quase 6 milhões de argentinos já têm dívidas atrasadas há mais','https://g1.globo.com/economia/noticia/2026/09/07/trabalhar-dever-trabalhar-mais-como-credito-caro-prende-entregadores-argentinos-aos-aplicativos.ghtml','https://s2-g1.glbimg.com/yAFcLv_ly1vm1b9zRQgIDhPkN2w=/i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2026/y/B/AGYX5rTkmzdOotus0lCw/2026-07-26t143423z-2081005882-rc2qlmak1dd3-rtrmadp-3-argentina-milei-rural.jpg','2026-09-07 05:00:00','','','','Entregadores argentinos recorrem a crédito oferecido por aplicativos para cobrir despesas de trabalho. A reportagem aborda como juros altos e endividamento podem aumentar sua dependência dessas plataformas.','excerpt','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('39','36d1d3a7af4bca4cd7da0c35e9562e8ecb9891327237042d4ca670b1ffc316c4','mundo','g1 · Mundo','Mundo','Avalanche em montanha deixa ao menos 11 mortos no norte do Cáucaso, na Rússia','Outras seis ficaram feridas após avalanche atingir um grupo de 33 alpinistas na região de Kabardino-Balkaria.','https://g1.globo.com/mundo/noticia/2026/09/07/avalanche-em-montanha-na-russia.ghtml','','2026-09-07 04:19:41','','','','Uma avalanche atingiu um grupo de 33 alpinistas no norte do Cáucaso, na Rússia. O relato informa pelo menos 11 mortes e outras seis pessoas feridas.','excerpt','');
