INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('41','9133ee04049caa62b2ead8124145f638d4174d8470fdbbc0b58fc49bfe5a6ed9','mundo','g1 · Mundo','Mundo','Havaí entra em estado de emergência com aproximação do furacão Lowell','Furacão de categoria 3 deve passar a oeste das ilhas entre segunda e terça-feira, com previsão de chuva forte, ventos intensos e ondas de até 9 metros.','https://g1.globo.com/meio-ambiente/noticia/2026/09/06/havai-entra-em-estado-de-emergencia-com-aproximacao-do-furacao-lowell.ghtml','https://s2-g1.glbimg.com/-wmsLv7g6uWGITWY_Jc1n_yx2YU=/i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2026/I/w/VbC7flSlazz1pXiCO9bQ/zj3n9dm7nh4dwsrtmzfypfg2tyhntnxcv1cxtcki7czjq-m57id9ldja-3wut5by3yizhdupjwbpnw-uzlnvyrmmak3ytqzxguew3zavgo6kgd3t3cwyywf1u4v5g7dr9exaq8hxeluhugbgctaoizgczdvf9.jpg','2026-09-06 22:15:34','','','','O Havaí declarou emergência diante da aproximação do furacão Lowell. A previsão citada inclui chuva intensa, ventos fortes e ondas de até nove metros, com passagem a oeste das ilhas.','excerpt','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('42','91e1191db4409faac6512ad51b2c465eef662cd73818203baa630218f06da026','mundo','g1 · Mundo','Mundo','Extrema direita AfD conquista vitória histórica em eleição regional alemã','Legenda supera os partidos tradicionais e chega ao maior resultado de sua história em um estado alemão, mas ainda precisa garantir maioria para formar o governo.','https://g1.globo.com/mundo/noticia/2026/09/06/extrema-direita-afd-conquista-vitoria-historica-em-eleicao-regional-alema.ghtml','https://s2-g1.glbimg.com/h6Q5dJILczZz_XFq7kOADn4qUYc=/i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2026/m/K/srR9JySMmReQJknAKYsQ/2026-09-06t205139z-2093134816-rc2vdnandkf5-rtrmadp-3-germany-election-saxony-anhalt-afd.jpg','2026-09-06 19:37:39','','','','A AfD alcançou seu melhor resultado em uma eleição estadual alemã, superando partidos tradicionais. A formação do governo ainda depende da obtenção de maioria.','excerpt','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('43','d64698a2a14ef4237c70f210ad47c5e5899b751abfb65700fdc39302259f7329','mundo','g1 · Mundo','Mundo','Avião cargueiro da Amazon sai da pista em Miami e deixa 5 mortos','Aeronave Boeing 767 operada para a Amazon havia acabado de pousar no Aeroporto Internacional de Miami; FAA confirmou o incidente e informou que vai investigar o caso.','https://g1.globo.com/mundo/noticia/2026/09/06/aviao-amazon-cai.ghtml','https://s2-g1.glbimg.com/z-LWC_-H6XAIPpyVaviyWSzmaVA=/i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2026/B/u/hIpdcrRCy1CH0mIUR7rQ/2026-09-06t194934z-1184906547-rc2vdna036ma-rtrmadp-3-usa-crash-plane-miami.jpg','2026-09-06 16:10:16','','','','Um cargueiro Boeing 767 operado para a Amazon saiu da pista após pousar em Miami, deixando cinco mortos. A autoridade de aviação americana informou que investigará o incidente.','excerpt','');
