INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('45','e6c81efdf882f79908c06849bbf323a9f9bea1e030f27f6177cae50cacc8b791','mundo','g1 · Mundo','Mundo','AfD diz ter \'mandato para governar\' após liderar projeções na Saxônia-Anhalt; oposição descarta apoio','Partido de extrema direita teria 39 cadeiras no Parlamento estadual, segundo estimativas divulgadas pela imprensa alemã, três a menos que a maioria absoluta. CDU e outras siglas rejeitam acordo com a legenda.','https://g1.globo.com/mundo/noticia/2026/09/06/afd-saxonia-anhalt-eleicoes.ghtml','https://s2-g1.glbimg.com/UZ7EvEnJAsAEskEtUiK6RNKXthc=/i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2026/d/y/ihObkGQrarlD46AFYaTg/2026-09-06t162039z-1067039188-rc2sdnacde8h-rtrmadp-3-germany-election-saxony-anhalt-afd.jpg','2026-09-06 14:50:39','','','','A AfD reivindicou condições de governar após liderar projeções eleitorais na Saxônia-Anhalt. As estimativas a colocavam abaixo da maioria absoluta, enquanto outros partidos rejeitavam uma aliança.','excerpt','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('46','d6b1eed2e482e116a0918293466137626e72d127334671fcf70bdf1b25a23b5d','mundo','g1 · Mundo','Mundo','Governo Trump retoma tentativa na Suprema Corte dos EUA para limitar voto por correio','Governo recorre à Suprema Corte para tentar barrar novas restrições ao voto por correspondência antes das eleições de novembro.','https://g1.globo.com/mundo/noticia/2026/09/06/governo-trump-retoma-tentativa-na-suprema-corte-dos-eua-para-limitar-voto-por-correio.ghtml','https://s2-g1.glbimg.com/BCBNX725C_waegm3HJ5ZMAbpR_g=/i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2026/d/K/AZGE6KRSSWDABgK8YCNg/2026-09-02t181020z-2101691279-rc26bnagxs5e-rtrmadp-3-usa-trump.jpg','2026-09-06 14:26:53','','','','O governo Trump voltou à Suprema Corte em uma disputa sobre restrições ao voto por correspondência antes das eleições americanas de novembro.','excerpt','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('47','c8f3f781240d6fe50d04d7c2249be1119e9e448f40fac4a0c19bc7383b2033e2','mundo','g1 · Mundo','Mundo','Mulher é encontrada viva no Nepal dias após família iniciar rituais fúnebres','Dada como morta pela família, Chandika Kumari Shrestha foi encontrada viva 10 dias após as enchentes que devastaram o Nepal, presa em uma bolsa de ar sob os escombros de sua casa.','https://g1.globo.com/mundo/noticia/2026/09/06/mulher-e-encontrada-viva-no-nepal-dias-apos-familia-iniciar-rituais-funebres.ghtml','https://s2-g1.glbimg.com/c0k4KaiV5bLWYuZSD53YMOwpGZY=/i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2026/q/O/ob9z1RSQqgfknBnWyzKw/6bvy7linorms7ak46yhliqg6t4.jpg','2026-09-06 14:21:02','','','','Chandika Kumari Shrestha foi localizada viva sob os escombros de sua casa no Nepal dez dias após enchentes. A família já havia iniciado cerimônias fúnebres por considerá-la morta.','excerpt','');
