INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('84','fe07575c2da78feb886bff471ce8e807812f4512e7894dc5c301c336a09203ac','tecnologia','g1 · Tecnologia','Tecnologia','Como será viajar no jato da Embraer que consegue pousar sozinho','Novo jato leve da Embraer poderá levar até 10 passageiros, voar a mais de 800 km/h e realizar pouso de emergência de forma automática.','https://g1.globo.com/tecnologia/noticia/2026/09/04/como-sera-viajar-no-jato-da-embraer-que-consegue-pousar-sozinho.ghtml','https://s2-g1.glbimg.com/r0JbUM37-_IgabwfPipDx_Sfthg=/i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2026/4/x/rKxsfYRzWBG0hFUnh2dw/embraer-phenom-300ev.gif','2026-09-04 05:12:31','','','','A Embraer prepara um jato leve para até dez passageiros, com velocidade superior a 800 km/h e recurso de pouso automático em emergência.','excerpt','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('85','9b0988321562fd7c20895bcb94f3e087d575d49469921baa220307e3ba26f9d6','tecnologia','g1 · Tecnologia','Tecnologia','Apple é processada nos EUA por patentes de reconhecimento facial em iPhones','Empresa química BASF diz que dona dos iPhones usa sua tecnologia contra falhas em sistemas de reconhecimento facial em vários celulares e tablets.','https://g1.globo.com/tecnologia/noticia/2026/09/03/apple-e-processada-nos-eua-por-patentes-de-autenticacao-facial-em-iphones.ghtml','https://s2-g1.glbimg.com/k3yBUlBrFj1RcucTv3dSiC3J45w=/i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2026/P/9/AiosWYQTKMWxUj11kWgA/2026-06-01t074149z-226100092-rc21vgaq2k1b-rtrmadp-3-global-smartphones.jpg','2026-09-03 20:42:15','','','','A BASF processou a Apple nos Estados Unidos por suposto uso de patentes ligadas ao reconhecimento facial. A acusação envolve tecnologias presentes em celulares e tablets.','excerpt','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('86','1ab9de69320c4576171640e5f1f5b11998581f8c3d1d9fd6f2787cde5b8540de','tecnologia','g1 · Tecnologia','Tecnologia','OpenAI lança modelo de IA com \'desligamento automático\' após ataque por seus próprios sistemas','Segundo a criadora do ChatGPT, este é o seu modelo de IA mais alinhado às instruções dos usuários. Em julho, agentes de IA da OpenAI superaram barreiras e realizaram invasão a sistemas de outra empresa.','https://g1.globo.com/tecnologia/noticia/2026/09/03/openai-gpt-6-astra-modelo-inteligencia-artificial.ghtml','https://s2-g1.glbimg.com/oFEJ2cCF-s-aJRT_SUnXEgtvLUM=/i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2026/E/u/PoTn79SBmiJX5eZIc08g/press-static.png','2026-09-03 15:00:58','','','','A OpenAI anunciou um modelo com recurso de desligamento automático após um incidente envolvendo seus agentes. A empresa o apresenta como mais alinhado às instruções dos usuários.','excerpt','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('87','07477a0c7df9e98e3f323bd670c753a8195a1924f208f6978a99b5e1e22fc3fa','tecnologia','g1 · Tecnologia','Tecnologia','ChatGPT fora do ar? Usuários relatam instabilidade nesta quinta-feira','Instabilidade afetou o serviço nesta quinta-feira (3), e número de reclamações atingiu pico de 10 mil registros no Downdetector. Procurada, a OpenAI ainda não se manifestou sobre o problema.','https://g1.globo.com/tecnologia/noticia/2026/09/03/chatgpt-fora-do-ar-usuarios-relatam-instabilidade-nesta-quinta-feira.ghtml','https://s2-g1.glbimg.com/pe94Q359wqIdm-3zMGTAKNXFJRg=/i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2026/0/B/meNGe2R6uqsHHMDF5fHw/afp-20260513-b2l38zv-v1-highres-filesfrancetechnologyaihealthpsychosis.jpg','2026-09-03 12:19:29','','','','Usuários relataram falhas no ChatGPT em 3 de setembro. O Downdetector registrou um pico de dez mil reclamações, e a chamada informa que a OpenAI ainda não havia se manifestado.','excerpt','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('88','ffc497d1a818f721be8af7a3cef7cc27c140548aa6d6bf167daa24991bc9be53','tecnologia','g1 · Tecnologia','Tecnologia','Governo Trump apoia OpenAI em ação movida pelo \'New York Times\' contra uso de conteúdo do jornal para treinar IA','Departamento de Justiça dos EUA afirma que benefícios econômicos, científicos e de segurança nacional do treinamento de IA superam os prejuízos alegados pelo jornal.','https://g1.globo.com/tecnologia/noticia/2026/09/03/governo-dos-eua-apoia-openai-em-acao-movida-pelo-new-york-times.ghtml','https://s2-g1.glbimg.com/Ywmnyulx05HJ8X4xrKIXWPdwSfU=/i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2026/m/t/7Pnun1TWWTMWcRuapJcw/afp-20260903-c77v8e7-v4-highres-topshotuspoliticstrump.jpg','2026-09-03 11:05:43','','','','O governo americano apoiou a OpenAI no processo movido pelo New York Times sobre treinamento de IA. O Departamento de Justiça argumentou que os benefícios superam os danos alegados pelo jornal.','excerpt','');
