INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('364','15af0f4c808c67d8c03e28f271dcb4ec1053be4ae00e44f7377a63fbc8ded481','g1','g1','Brasil','AGU prepara reação e aponta invasão de competência da Presidência em decisão de Mendonça','Advocacia-Geral da União sustentará que a decisão monocrática do ministro André Mendonça viola a prerrogativa exclusiva do presidente da República para nomear e exonerar o chefe da Polícia Federal.','https://g1.globo.com/politica/blog/andreia-sadi/post/2026/09/08/agu-afastamento-pf.ghtml','','2026-09-08 09:58:42','','','','A AGU prepara uma contestação ao afastamento do diretor da PF. Seu argumento é que a decisão de André Mendonça interfere na competência presidencial de nomear e exonerar o ocupante do cargo.','excerpt','');
