INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('398','0c6cfd4254f1a8bf1eef7cd881cceb7dc4eaaefc93e84ceb34e681693d6328f7','economia','g1 · Economia','Economia','Grindr aceita pagar R$ 180 milhões para encerrar ação no Reino Unido por vazamento de dados, diz jornal','O aplicativo de relacionamentos era acusado por milhares de usuários de compartilhar informações privadas e status de HIV com empresas de publicidade. As informações são do The Guardian.','https://g1.globo.com/tecnologia/noticia/2026/09/08/grindr-aceita-acordo-reino-unido.ghtml','https://s2-g1.glbimg.com/wxkDw4FlmpsRyxaM2gVjsUPiNXc=/i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2020/6/y/gppdK6QKGcfrizdZpjbg/grindr-reuters-aly-song.jpg','2026-09-08 09:40:14','','','','Segundo o The Guardian, o Grindr aceitou pagar R$ 180 milhões para encerrar uma ação no Reino Unido. Usuários acusavam o aplicativo de compartilhar dados privados, incluindo informações sobre HIV, com anunciantes.','excerpt','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('399','5d650c6c8e2a4673eecc298f966776f9095b6f717b59ea85ce4b9ddf4ec89830','economia','g1 · Economia','Economia','\'Dinheiro esquecido\': BC diz que R$ 5,6 bilhões podem ser resgatados; 23,6 milhões de pessoas têm direito','Em maio, o governo Lula anunciou o uso de parte dos recursos não retirados por clientes das instituições financeiras para viabilizar o Desenrola 2.0. TCU apura manobra; entenda.','https://g1.globo.com/economia/noticia/2026/09/08/dinheiro-esquecido-bc-diz-que-r-56-bilhoes-podem-ser-resgatados-236-milhoes-de-pessoas-tem-direito.ghtml','https://s2-g1.glbimg.com/V7uKJ7K0ogi3tOM0sEJIlBujADo=/i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2026/T/Z/uUFBmGQYOkiUHnBgSATg/73cc1fd0-8430-11f1-bee8-53ce494e1abc.jpg','2026-09-08 09:37:37','','','','O Banco Central informou que R$ 5,6 bilhões permanecem disponíveis para resgate por 23,6 milhões de pessoas. A reportagem também menciona apuração do TCU sobre o uso de parte dos recursos não retirados.','excerpt','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('400','dd56321913b02f6324ce55e8548648e1a9e5fcbbc62597b9b026d7927456a5de','economia','g1 · Economia','Economia','Dólar abre em queda nesta terça-feira, de olho em alta do petróleo e cenário eleitoral','Na última sexta-feira (4), a moeda americana subiu 0,50%, cotada a R$ 5,1300. Já a bolsa brasileira recuou 0,02%, aos 185.147 pontos.','https://g1.globo.com/economia/noticia/2026/09/08/dolar-ibovespa.ghtml','https://s2-g1.glbimg.com/5b3No2jzOqlFV_iL1WjQlBxTNwQ=/i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2025/f/D/MS4yEaTkqIFoMjdGfx3A/2025-12-31t181616z-716243511-rc2tria44ux8-rtrmadp-3-usa-moneymarket-liquidity.jpg','2026-09-08 09:00:14','','','','O dólar iniciou a terça-feira em queda, com atenção dos investidores ao petróleo e às eleições. No fechamento anterior citado, a moeda estava em R$ 5,13.','excerpt','');
