INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('484','53ef8146d79dab6987361d3e19a799e95e143e359795b33a1b289a2468ccc6ea','uolesporte','UOL Esporte','Esportes','\'Missão do Palmeiras tem que ser chegar com 2 pontos de diferença para o jogo em casa\', comenta Lavieri','','https://mais.uol.com.br/v/17415408','https://thumb.mais.uol.com.br/17415408.jpg?ver=1','2026-09-08 10:12:59','','','','Danilo Lavieri considera decisivo que o Palmeiras chegue ao confronto com o Flamengo, na 36ª rodada, no máximo dois pontos atrás. Nesse cenário, uma vitória em casa poderia mudar a liderança, transformando o encontro em uma decisão direta pelo título.\n\nA análise aparece em um debate do UOL News Esporte sobre a dificuldade da perseguição ao líder. Os comentaristas também discutem o calendário palmeirense e a vantagem rubro-negra nos critérios de desempate. São avaliações sobre a disputa, e não uma previsão de resultado.','article','https://www.uol.com.br/esporte/futebol/ultimas-noticias/2026/09/08/palmeiras-vai-ter-que-melhorar-para-acompanhar-o-flamengo-diz-arnaldo.amp.htm');
