INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('486','0bd1cb6f6b1e406b527d9c7f8dfba14f7a50d3ae71783ae108e94f281c0f0bb3','uolesporte','UOL Esporte','Esportes','Onde vai passar Real Madrid x Inter de Milão pela Liga dos Campeões? Como assistir','','https://www.uol.com.br/esporte/ultimas-noticias/2026/09/08/onde-vai-passar-real-madrid-x-internazionale-pela-liga-dos-campeoes-como-assistir-ao-vivo.ghtm','https://conteudo.imguol.com.br/c/esporte/ea/2026/08/26/mbappe-comemora-gol-com-vini-jr-pelo-real-madrid-contra-a-real-sociedad-pelo-campeonato-espanhol-1787777888343_v2_142x100.jpg','2026-09-08 10:00:00','','','','Real Madrid e Inter de Milão estreiam na fase inicial da Champions em um confronto no Santiago Bernabéu, em Madri. A reportagem publicada antes da partida informa início às 16h de Brasília, em 8 de setembro, com exibição por SBT, TNT e HBO Max. Na TV aberta, a disponibilidade pode depender da região; no streaming, do plano contratado.\n\nOs espanhóis chegam tentando reagir à derrota por 1 a 0 para o Betis no campeonato nacional. A Inter, por sua vez, vinha de um começo de temporada com aproveitamento perfeito na liga italiana e buscava levar esse embalo para um resultado fora de casa.','article','https://www.uol.com.br/esporte/ultimas-noticias/2026/09/08/onde-vai-passar-real-madrid-x-internazionale-pela-liga-dos-campeoes-como-assistir-ao-vivo.amp.htm');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('487','5a12ebb1a66ef72f045fc9fb636f260d75c045bdd98e92d98a3a215b7203b501','uolesporte','UOL Esporte','Esportes','Yamal descarta \'campanha\' para vencer Bola de Ouro: \'Não vou implorar\'','','https://www.uol.com.br/esporte/futebol/ultimas-noticias/2026/09/08/lamine-yamal-bola-de-ouro.ghtm','https://conteudo.imguol.com.br/c/esporte/4b/2026/07/13/lamine-yamal-em-acao-durante-jogo-da-espanha-na-copa-do-mundo-1783996393799_v2_142x100.jpg','2026-09-08 09:55:14','','','','Yamal descartou fazer uma campanha pessoal para conquistar a Bola de Ouro e afirmou que não pretende pedir apoio à sua candidatura.','title','');
