INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('515','1c85947d0f6d7a6d19d86c741c4a6b64aee4df03ef353bfbc877f1b35c63ffbb','gshow','gshow','Famosos','\'Edição de colecionador\': dia com Elton John, Gilberto Gil e lendas da música no Rock in Rio ganha elogios na web','Quarto dia de festival reuniu estes e grandes nomes na Cidade do Rock na última segunda-feira (7)','https://gshow.globo.com/festivais/rock-in-rio/2026/noticia/edicao-de-colecionador-dia-com-elton-john-gilberto-gil-e-lendas-da-musica-no-rock-in-rio-ganha-elogios-na-web.ghtml','https://s2-gshow.glbimg.com/olFtdFtzsZmR8K9H5OE0czUBiPk=/i.s3.glbimg.com/v1/AUTH_e84042ef78cb4708aeebdf1c68c6cbd6/internal_photos/bs/2026/Z/U/1ld9JkTTKIrFRVGN7cAA/elto-john-gilberto-gil.png','2026-09-08 00:00:42','','','','O quarto dia do Rock in Rio de 2026 ganhou repercussão positiva nas redes ao reunir nomes de diferentes gerações da música. Na cobertura do gshow, Elton John, Gilberto Gil, Péricles e Roupa Nova aparecem entre os destaques de uma programação elogiada pelos fãs em 7 de setembro.\n\nO dia também teve encontros no palco: Vanessa da Mata recebeu Rubel, Luísa Sonza dividiu uma apresentação com Roberto Menescal e Guilherme Arantes cantou com o Roupa Nova. Belo esteve acompanhado dos participantes do Estrelas da Casa, enquanto a bailarina Ingrid Silva participou do show de Jon Batiste.\n\nA reportagem reúne registros em vídeo desses momentos, da homenagem de Péricles ao repertório da Motown e das apresentações de Laufey e Elton John. Assim, a repercussão vai além de uma única atração e destaca a variedade de artistas e participações da noite.','article','https://gshow.globo.com/festivais/rock-in-rio/2026/noticia/edicao-de-colecionador-dia-com-elton-john-gilberto-gil-e-lendas-da-musica-no-rock-in-rio-ganha-elogios-na-web.ghtml');
