INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('521','9a8f32207d321155914de05b7ef578ebbdcb110106946c0d2d5c914002dce080','gshow','gshow','Famosos','Quem Ama Cuida: Ademir flagra Dora e André na cama','Em Quem Ama Cuida, Adriana arma para advogado encontrar a ex com seu sobrinho','https://gshow.globo.com/novelas/quem-ama-cuida/vem-por-ai/noticia/quem-ama-cuida-ademir-flagra-dora-e-andre-na-cama.ghtml','https://s2-gshow.glbimg.com/y4VI14xgIOkW4DVTZ1Z__iWGT4g=/i.s3.glbimg.com/v1/AUTH_e84042ef78cb4708aeebdf1c68c6cbd6/internal_photos/bs/2026/V/S/vLjLyCSG67HdUuqspdaw/quem-ama-cuida-qm087163-v1.mp4.00-05-46-23.still002.jpg','2026-09-07 22:50:00','','','','Na novela Quem Ama Cuida, uma armação de Adriana leva Ademir a encontrar Dora na cama com André, sobrinho dele.','excerpt','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('522','1d75097a8a42aebc7f29f2bc971637c0804beb3673c5d2dd3e384c49d25802a2','gshow','gshow','Famosos','Qual famosa ignorou o frio no quarto dia de Rock in Rio e arrasou no look?','','https://gshow.globo.com/festivais/rock-in-rio/2026/votacao/qual-famosa-ignorou-o-frio-no-quarto-dia-de-rock-in-rio-e-arrasou-no-look-PSH5dDdmLw.ghtml','https://s2-gshow.glbimg.com/NBwcAx06y8aEhz8APlnzA_DjICI=/i.s3.glbimg.com/v1/AUTH_e84042ef78cb4708aeebdf1c68c6cbd6/internal_photos/bs/2026/x/8/udxY8sTqGAySWt4BNaDw/famosas-quarto-dia-de-rock-in-rio.jpg','2026-09-07 22:44:13','','','','A publicação chama atenção para o visual de uma famosa no quarto dia do Rock in Rio, mas a manchete não identifica quem é ela.','title','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('523','d8be40a85bf1ab7a022a16b6d6cc0bf617d42159fdd92a89f906fa2fc7c22de6','agenciabrasil','Agência Brasil','Economia','Mercado financeiro reduz previsão da inflação para 5% este ano','A previsão do mercado financeiro para o Índice Nacional de Preços ao Consumidor Amplo (IPCA), referência oficial da inflação no país, passou de 5,01% para 5% este ano. A estimativa está no Boletim Focus desta terça-feira (8), pesquisa divulgada semanalmente p…','https://agenciabrasil.ebc.com.br/economia/noticia/2026-09/mercado-financeiro-reduz-previsao-da-inflacao-para-5-este-ano','','2026-09-08 10:02:00','A previsão do mercado financeiro para o Índice Nacional de Preços ao Consumidor Amplo (IPCA), referência oficial da inflação no país, passou de 5,01% para 5% este ano. A estimativa está no Boletim Focus desta terça-feira (8), pesquisa divulgada semanalmente pelo Banco Central (BC) com a expectativa de instituições financeiras para os principais indicadores econômicos.\n\nA previsão está acima do intervalo da meta que deve ser perseguida pelo BC. Estabelecida pelo Conselho Monetário Nacional (CMN), a meta é 3%, com intervalo de tolerância de 1,5 ponto percentual. Ou seja, o limite inferior é 1,5% e o superior, 4,5%.\n\nNotícias relacionadas:\n\nBoletim Focus: mercado prevê redução da inflação e do PIB de 2026 .\n\nPrévia da inflação fica em -0,40%, a menor desde agosto de 2022.\n\nNo mês de julho, os alimentos ficaram mais baratos e contribuíram para que a inflação oficial perdesse força pelo quarto mês seguido e fechar em 0,07%, de acordo com o Instituto Brasileiro de Geografia e Estatística (IBGE). O resultado fez o IPCA acumular 4,44% em 12 meses, trazendo o indicador de volta para a meta do governo.\n\nA inflação de agosto será divulgada na próxima sexta-feira (11) pelo IBGE.\n\nPara 2027, a projeção da inflação variou de 4,28% para 4,29%. Para 2028 e 2029, as estimativas são de 3,8% e 3,5%, respectivamente.\n\nTaxa Selic\n\nPara alcançar a meta de inflação, o Banco Central usa como principal instrumento a taxa básica de juros, a Selic, definida atualmente em 14% ao ano pelo Comitê de Política Monetária (Copom) do BC. Na última reunião, em agosto, o colegiado reduziu a Selic em 0,25 ponto percentual, pela quarta vez seguida.\n\nDe junho de 2025 a março deste ano, a Selic ficou em 15% ao ano, o maior nível em quase 20 anos. O Copom voltou a cortar os juros na reunião de março, num cenário de queda da inflação. No entanto, a guerra no Oriente Médio, que se refletiu no aumento dos preços de combustíveis e de alimentos, dificulta a queda da taxa.\n\nO próximo encontro do Copom para definir a Selic será nos dias 15 e 16 de setembro.\n\nNesta edição do Focus, a estimativa dos analistas de mercado é que a taxa básica chegue a 13,75% ao ano até o fim de 2026. Para 2027 e 2028, a previsão é que a Selic seja reduzida para 12% ao ano e 10,5% ao ano, respectivamente. Em 2029, a taxa deve ficar em 10% ao ano.\n\nQuando o Copom aumenta a Selic, a finalidade é conter a demanda aquecida, o que causa reflexos nos preços, porque os juros mais altos encarecem o crédito e estimulam a poupança. Assim, taxas mais altas também podem dificultar a expansão da economia.\n\nOs bancos ainda consideram outros fatores na hora de definir os juros cobrados dos consumidores, como risco de inadimplência, lucro e despesas administrativas.\n\nQuando a Taxa Selic é reduzida, a tendência é que o crédito fique mais barato, com incentivo à produção e ao consumo, diminuindo o controle sobre a inflação e estimulando a atividade econômica.\n\nPIB e câmbio\n\nNesta edição do boletim do Banco Central, a estimativa das instituições financeiras para o crescimento da economia brasileira este ano saiu de 1,92% para 1,93%. Para 2027, a projeção para o Produto Interno Bruto (PIB, a soma dos bens e serviços produzidos no país) permanece em 1,5%. Para 2028 e 2029, o mercado financeiro estima expansão do PIB em 1,96% e 2%, respectivamente.\n\nNo segundo trimestre de 2026, a economia do país cresceu ​0,5% na comparação com o primeiro trimestre. No acumulado de 12 meses, houve expansão de 1,9%, de acordo com o IBGE.\n\nEm 2025, a economia brasileira cresceu 2,3%, com expansão em todos os setores e destaque para a agropecuária. O resultado representa o quinto ano seguido de crescimento.\n\nNo Focus desta semana, a previsão da cotação do dólar está em R$ 5,20 para o final deste ano. No fim de 2027, estima-se que a moeda norte-americana fique em R$ 5,30.','Da Agência Brasil','https://www.ebc.com.br/termos-de-uso-e-condicoes-gerais-do-portal-da-ebc','A projeção do mercado para a inflação de 2026 recuou de 5,01% para 5% no Boletim Focus de 8 de setembro. A redução é pequena e a expectativa ainda supera o teto de 4,5% da meta. Para o crescimento econômico, a estimativa avançou de 1,92% para 1,93%.\n\nOs analistas consultados pelo Banco Central esperam que a Selic, então em 14% ao ano, termine 2026 em 13,75%. O próximo encontro do Copom está marcado para 15 e 16 de setembro. A reportagem observa que os cortes de juros ocorrem em meio à desaceleração da inflação, mas que o conflito no Oriente Médio pressiona combustíveis e alimentos.\n\nPara o câmbio, a previsão é de dólar a R$ 5,20 no encerramento do ano. Esses números representam expectativas das instituições participantes da pesquisa, e não resultados já confirmados da economia.','full','https://agenciabrasil.ebc.com.br/economia/noticia/2026-09/mercado-financeiro-reduz-previsao-da-inflacao-para-5-este-ano');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('524','75afade4fc3950c3bcee131399c0602ec9dd16ec4fea344730eb4284fbeb6812','agenciabrasil','Agência Brasil','Brasil','Mendonça afasta Andrei Rodrigues da direção-geral da Polícia Federal ','O ministro André Mendonça, relator do caso do Banco Master no Supremo Tribunal Federal (STF), decidiu nesta terça-feira (8) afastar o diretor-geral da Polícia Federal, Andrei Rodrigues, de suas funções. Mendonça também afastou preventivamente o diretor de Int…','https://agenciabrasil.ebc.com.br/justica/noticia/2026-09/mendonca-afasta-andrei-rodrigues-da-direcao-geral-da-policia-federal','','2026-09-08 09:27:00','O ministro André Mendonça, relator do caso do Banco Master no Supremo Tribunal Federal (STF), decidiu nesta terça-feira (8) afastar o diretor-geral da Polícia Federal, Andrei Rodrigues, de suas funções. \n\nMendonça também afastou preventivamente o diretor de Inteligência da PF, Leandro Almada. O ministro atendeu a pedido do partido Novo.\n\nNotícias relacionadas:\n\nFachin dá 5 dias para Mendonça e Gonet responderem acusação de Moraes.\n\nMoraes encaminha a Fachin pedido de investigação contra Mendonça.\n\nMendonça quer levar ao plenário diálogos atribuídos a Vorcaro e Moraes.\n\nO ministro justificou a urgência da medida diante do que disse ser a “superlativa gravidade” e “ilicitude” da divulgação de “relatórios de inteligência” da PF pelo ministro Alexandre de Moraes, também do Supremo. \n\nO movimento ocorre após Moraes ter tornado público, na semana passada, um relatório da PF em que se sugere um possível direcionamento das investigações do caso Master contra desafetos políticos de Mendonça. O documento, contudo, não é assinado nem possui o cabeçalho da PF. \n\n“Inicialmente, verifica-se que o ‘documento’ é apócrifo, sem timbre ou qualquer outro símbolo gráfico capaz de lhe empregar o mínimo grau de legitimidade e confiabilidade, inviabilizando qualquer conferência quanto à sua autoria e data de elaboração”, destacou Mendonça. \n\n\"[O episódio] impõe a adoção de providências imediatas para evitar que as prerrogativas da magistratura, da advocacia pública e da própria atividade policial continuem sendo vilipendiadas”, escreveu o ministro. \n\nA Agência Brasil busca posicionamento da Polícia Federal. Até o momento, a corporação não se manifestou. \n\nMonitoramento sistemático\n\nMendonça destacou ainda que o relatório em questão faz ele próprio o alerta de que suas “inferências” são “sem valor probatório”.\n\nO ministro cita ofício assinado por Andrei Rodrigues dando conta de que ao menos seis relatórios do tipo foram produzidos tendo Mendonça como alvo, os quais teriam sido recebidos pelo diretor-geral da PF entre os dias 3 e 31 de agosto de 2026.\n\n“Ou seja, ao menos há mais de 30 dias este relator tem sido monitorado pela Polícia Federal. Trata-se de monitoramento ilícito de Ministro da Suprema Corte do país, o que por si só revela a gravidade da situação”, escreveu. \n\nEm sua decisão, o ministro esmiúça o teor do relatório divulgado por Moraes e aponta para o fato de que o próprio documento afirma se tratar de conjecturas que não autorizariam “providências formais”, mas sugere a continuidade do monitoramento e coleta de informações tendo Mendonça como alvo. \n\n“Importa registrar que este relator foi submetido a monitoramento sistemático por parte da inteligência da Polícia Federal”, escreveu o ministro. \n\nGuerra de relatórios \n\nO relatório foi tornado público por Alexandre de Moraes no âmbito do chamado inquérito das Fake News, do qual ele é relator e que possui como objeto original ameaças e notícias falsas tendo como alvo ministros do Supremo. Tal processo, entretanto, foi aberto há mais de sete anos e possui múltiplas frentes de investigação.\n\nMoraes enviou o documento ao ministro Edson Fachin, presidente do STF, apontando o que seriam atos de abuso de autoridade, improbidade administrativa e crime de responsabilidade por parte de Mendonça. \n\nA atitude foi tomada em resposta à divulgação por Mendonça de um relatório de investigação da Operação Compliance Zero com mensagens que teriam sido enviadas a Moraes no ano passado pelo ex-banqueiro Daniel Vorcaro, antigo dono do Banco Master e suspeito de praticar fraudes financeiras bilionárias e corromper agentes públicos. \n\nNas mensagens, recuperadas a partir do celular apreendido de Vorcaro, o ex-banqueiro aparenta ter relação de proximidade com o interlocutor, que a PF diz ser Moraes. Uma delas sugere, por exemplo, que o ministro recebeu e editou um contrato de R$ 131 milhões do Master com o escritório de advocacia de sua esposa, a advogada Viviane Barci de Moraes. \n\nEm outra mensagem, Vorcaro parece buscar junto a Moraes informações sobre uma possível operação da Polícia Federal para prendê-lo. Moraes, por sua vez, negou qualquer contato com o ex-banqueiro.\n\nTexto ampliado às 10h35','Felipe Pontes – repórter da Agência Brasil','https://www.ebc.com.br/termos-de-uso-e-condicoes-gerais-do-portal-da-ebc','André Mendonça determinou o afastamento de Andrei Rodrigues da direção-geral da Polícia Federal e de Leandro Almada da área de Inteligência. A decisão, tomada no âmbito do caso Banco Master, atendeu a um pedido do partido Novo.\n\nO ministro questionou relatórios divulgados por Alexandre de Moraes e afirmou que teria sido monitorado pela PF. Segundo a reportagem, um dos documentos não tinha assinatura nem identificação institucional, e seu próprio conteúdo indicava que as inferências não constituíam prova. Mendonça usou esses pontos para justificar a medida.\n\nO episódio integra uma disputa entre ministros sobre documentos e mensagens ligados às investigações do banco. Moraes havia encaminhado acusações contra Mendonça ao presidente do STF e negou contato com o ex-banqueiro Daniel Vorcaro. Até a publicação, a Agência Brasil ainda aguardava manifestação da Polícia Federal. As acusações relatadas permanecem atribuídas aos envolvidos.','full','https://agenciabrasil.ebc.com.br/justica/noticia/2026-09/mendonca-afasta-andrei-rodrigues-da-direcao-geral-da-policia-federal');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('525','97c9f5a42e69e1480045ea6bd34a44eb417ad2feaf842573c1d2ce293bcab0f6','agenciabrasil','Agência Brasil','Brasil','Confira a agenda dos presidenciáveis nesta terça-feira (8)','A agenda dos presidenciáveis nesta terça-feira (8) inclui entrevistas, reuniões com apoiadores e visitas técnicas pelo país. Há ainda participação em sabatina e encontro com lideranças locais. Renan Santos (Missão) Às 8h, participa de sabatina na Jovem Pan, e…','https://agenciabrasil.ebc.com.br/politica/noticia/2026-09/confira-agenda-dos-presidenciaveis-nesta-terca-feira-8','','2026-09-08 08:58:00','A agenda dos presidenciáveis nesta terça-feira (8) inclui entrevistas, reuniões com apoiadores e visitas técnicas pelo país.\n\nHá ainda participação em sabatina e encontro com lideranças locais.\n\nRenan Santos (Missão)\nÀs 8h, participa de sabatina na Jovem Pan, em  São Paulo (SP). Às 9h30, concede entrevista a Paulo Mathias TV, também em São Paulo.\n\nRomeu Zema (Novo)\nÀs 17h30, participa junto com o vice Girão de reunião com a Associação Brasileira de Emissoras de Rádio e Televisão (Abert), em Brasília.\n\nRonaldo Caiado (PSD)\nÀs 10h30, visita o Centro Nacional de Pesquisa em Energia e Materiais (Cnpem). Às 12h, tem encontro com lideranças da região de Jaguariúna.\n\nRui Costa Pimenta (PCO)\nÀs 13h, participa do programa Análise da 3ª, na Rádio Causa Operária. Às 20h, concede entrevista ao canal do Galo Preto, com Leandro Fortes.D8.\n\nSamara Martins (UP)\nÀs 14h, participa de sabatina do jornal Correio Braziliense, de Brasília (DF). Às 17h, concede entrevista ao portal Metrópoles. E às 18h, realiza caminhada na Rodoviária do Plano Piloto, no centro de Brasília.\n\nWilson Grassi (Democrata)\nÀs 11h, concede entrevista ao jornalista Lucas França. Às 14h, participa de sabatina com membros do grupo Dados Políticos.\n\nAugusto Cury (Avante)\nÀs 8h30, tem entrevista para O Estado de S. Paulo. Às 16h30, concede entrevista ao Canal Meio. Às, 17h, o candidato à vice na chapa, Júlio Delgado, estará na sabatina da RedeTV!\n\n​Clariana Barão (DC)\nConcede entrevista à rádio Agora FM (92.5), de Rondonópolis (MT), às 11h30, e à rádio Capela FM (105.9), de Vinhedo (SP), às 14h.\n\nEdmilson Costa (PCB)\nO candidato está em Lisboa, Portugal, cumprindo agenda da secretaria-geral de seu partido, o PCB.\n\nHertz Dias (PSTU)\nPassa parte do dia em Jacareí (SP), onde se reúne com apoiadores às 9h. Visita a Ocupação Coração Valente, às 11h, e a Fábrica Armco, às 13h20. Em seguida, vai para São Bernardo do Campo (SP), onde faz panfletagem na ETE Lauro Gomes, às 17h. Participa da Batalha da Matrix, às 19h.\n\nOs candidatos Flávio Bolsonaro (PL) e Luiz Inácio Lula da Silva (PT) não têm agenda pública de campanha.\n\nA ordem de apresentação da agenda dos candidatos a presidente segue rodízio diário em ordem alfabética.\n\n*Colaboraram Alex Rodrigues e Andreia Verdélio.','Da Agência Brasil*','https://www.ebc.com.br/termos-de-uso-e-condicoes-gerais-do-portal-da-ebc','As campanhas presidenciais de 8 de setembro se dividem entre entrevistas, sabatinas, reuniões e visitas. Renan Santos tem compromissos com veículos de comunicação em São Paulo, enquanto Romeu Zema participa de um encontro com a associação de emissoras de rádio e televisão em Brasília.\n\nRonaldo Caiado visita um centro de pesquisa e se reúne com lideranças da região de Jaguariúna. Samara Martins combina entrevistas com uma caminhada na Rodoviária do Plano Piloto. Hertz Dias tem agenda com apoiadores, uma ocupação e atividades em cidades paulistas.\n\nA relação também inclui compromissos de Rui Costa Pimenta, Wilson Grassi, Augusto Cury, Clariana Barão e Edmilson Costa. Segundo a agenda divulgada pela Agência Brasil, Lula e Flávio Bolsonaro não tinham atividades públicas de campanha anunciadas para esse dia.','full','https://agenciabrasil.ebc.com.br/politica/noticia/2026-09/confira-agenda-dos-presidenciaveis-nesta-terca-feira-8');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('526','afdd7155fca3aa11d9089b14b2fab51d468bdc2f5ff77ced001f5c8ef9ee9806','agenciabrasil','Agência Brasil','Mundo','Rússia ataca Kiev após breve pausa para visita de enviados dos EUA','A Rússia bombardeou Kiev com drones e mísseis na madrugada desta terça-feira (8), retomando seus ataques aéreos após uma breve pausa para a visita dos negociadores de paz dos Estados Unidos (EUA). Três pessoas morreram, segundo o prefeito Vitali Klitschko, e …','https://agenciabrasil.ebc.com.br/internacional/noticia/2026-09/russia-ataca-kiev-apos-breve-pausa-para-visita-de-enviados-dos-eua','','2026-09-08 08:32:00','','Vladyslav e Smilianets e Anna Pruchnicka - Repórteres da Reuters*','','A Rússia retomou ataques com drones e mísseis contra Kiev após uma pausa para a visita de negociadores americanos. O prefeito da capital ucraniana informou três mortes.','excerpt','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('527','d65c17ffb9f08b2fa1ea5f47b9a897f0557c7631c1804478854f1e0465f7820c','agenciabrasil','Agência Brasil','Esportes','Vasco vai à final e decide título do Feminino A2 contra Itabirito','Dono da melhor campanha da Série A2 (segunda divisão) do Campeonato Brasileiro Feminino de futebol, o Vasco está na final da competição. Na noite da última segunda-feira (7), o Cruzmaltino voltou a derrotar o Atlético-PI, desta vez por 4 a 0, no Luso-Brasilei…','https://agenciabrasil.ebc.com.br/esportes/noticia/2026-09/vasco-vai-final-e-decide-titulo-do-feminino-a2-contra-itabirito','','2026-09-08 07:48:00','','Lincoln Chaves - Repórter da EBC','','O Vasco confirmou a vaga na final da Série A2 do Brasileiro Feminino ao vencer o Atlético-PI por 4 a 0 no Luso-Brasileiro. As cariocas já haviam ganhado a ida por 4 a 1 e mantiveram o controle da semifinal, com destaque para a participação das paraguaias Lourdes González e Vanessa Arce.\n\nO adversário na decisão será o Itabirito, que eliminou o Minas Brasília. Como teve a melhor campanha, o Vasco fará em casa a segunda partida da final. Datas e horários ainda dependiam de definição da CBF na publicação, e os dois jogos terão transmissão da TV Brasil.\n\nOs quatro semifinalistas já asseguraram presença na primeira divisão de 2027. Por isso, a final decide o título entre equipes que já conquistaram o principal objetivo de acesso à elite.','article','https://agenciabrasil.ebc.com.br/esportes/noticia/2026-09/vasco-vai-final-e-decide-titulo-do-feminino-a2-contra-itabirito');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('528','3f0d1ba79c8a4382e3d86975c3818e8701922432095e6d1550e516b38ab7f712','agenciabrasil','Agência Brasil','Brasil','Programa de Reforma Agrária inclui 2,4 mil quilombolas no Maranhão','O Instituto Nacional de Colonização e Reforma Agrária (Incra) reconheceu 2.451 famílias de comunidades quilombolas do Maranhão como beneficiárias do Programa Nacional de Reforma Agrária. A Portaria nº 2.173 autoriza o início da seleção das unidades familiares…','https://agenciabrasil.ebc.com.br/direitos-humanos/noticia/2026-09/programa-de-reforma-agraria-inclui-24-mil-quilombolas-no-maranhao','','2026-09-08 07:40:00','O Instituto Nacional de Colonização e Reforma Agrária (Incra) reconheceu 2.451 famílias de comunidades quilombolas do Maranhão como beneficiárias do Programa Nacional de Reforma Agrária. \n\nA Portaria nº 2.173 autoriza o início da seleção das unidades familiares incluídas no Cadastro Único para Programas Sociais do Governo Federal (CadÚnico).\n\nNotícias relacionadas:\n\nIncra inclui 1,6 mil famílias do MA em Programa da Reforma Agrária.\n\nO processo será feito por meio da Plataforma de Governança Territorial, sistema usado pelo Incra para o gerenciamento e a execução de ações relacionadas à política agrária.\n\nPrograma\n\nSegundo o Incra, a iniciativa está alinhada às normas que regulamentam a seleção e a permanência de famílias beneficiárias da reforma agrária, além das diretrizes do programa Terra da Gente, lançado pelo governo federal para atender ao público da Política Nacional de Reforma Agrária.','Agência Brasil','https://www.ebc.com.br/termos-de-uso-e-condicoes-gerais-do-portal-da-ebc','O Incra reconheceu 2.451 famílias quilombolas do Maranhão como beneficiárias do Programa Nacional de Reforma Agrária. A medida permite iniciar a seleção das unidades familiares cadastradas no CadÚnico, conforme a Portaria nº 2.173.\n\nA seleção será realizada pela Plataforma de Governança Territorial, sistema usado pelo instituto para administrar ações da política agrária. Segundo o Incra, a iniciativa segue as regras de entrada e permanência das famílias no programa e está alinhada às diretrizes do Terra da Gente. A publicação trata do reconhecimento e do início desse processo, sem informar a conclusão de benefícios individuais.','full','https://agenciabrasil.ebc.com.br/direitos-humanos/noticia/2026-09/programa-de-reforma-agraria-inclui-24-mil-quilombolas-no-maranhao');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('529','d176550ac91c030602b1e36f68a0abf02ed43f11569569b7aff390c5e4690804','agenciabrasil','Agência Brasil','Brasil','Taxa média de recusa de doação de órgãos pelos familiares é 45%','O momento da perda de um ente querido é uma das situações mais dolorosas para uma família, que se vê diante da difícil decisão de autorizar ou não a doação de órgãos após a constatação de morte cerebral para salvar vidas de pessoas desconhecidas na fila de es…','https://agenciabrasil.ebc.com.br/saude/noticia/2026-09/taxa-media-de-recusa-de-doacao-de-orgaos-pelos-familiares-e-45','','2026-09-08 07:28:00','O momento da perda de um ente querido é uma das situações mais dolorosas para uma família, que se vê diante da difícil decisão de autorizar ou não a doação de órgãos após a constatação de morte cerebral para salvar vidas de pessoas desconhecidas na fila de espera. No Brasil, a taxa média de recusa familiar para a doação de órgãos gira em torno de 45%, índice que varia entre estados e até mesmo entre hospitais de uma mesma cidade, evidenciando que a recusa não depende apenas da população, mas também de fatores institucionais. \n\nSegundo o presidente da Associação de Medicina Intensiva Brasileira (AMIB), Cristiano Franke, muitos pacientes deixam seus familiares orientados sobre sua vontade de doar órgãos e muitas famílias também gostariam de fazer isso, atendendo a esse desejo. Entretanto, ele reforça, que, em muitos casos, a falha no acolhimento aos familiares e na comunicação dentro dos hospitais — tanto públicos quanto privados — é um dos principais obstáculos para a efetivação das doações.  \n\nNotícias relacionadas:\n\nHospital inicia protocolo de morte encefálica em jogador do Bragantino.\n\nHoje é Dia: prevenção ao suicídio e doação de órgãos são os destaques.\n\nSaúde incorpora transplante da membrana amniótica para tratar diabetes.\n\n“Muitas vezes as famílias não recebem todas as informações adequadamente, no momento e com um protocolo adequados para tomarem a melhor decisão. E muitas vezes também, as equipes médicas não estão preparadas para lidar com conversas difíceis, utilizando termos excessivamente técnicos e inacessíveis, ou realizando abordagens consideradas frias e comerciais em locais inadequados”, disse Franke. \n\nPor conta disso, a AMIB, em parceria com o Ministério da Saúde, capacitou, entre setembro de 2025 e agosto de 2026, 2.534 profissionais de saúde para atuar no processo de doação e transplantes de órgãos. Até o momento, o resultado, que já superou em 25% a meta inicial desse projeto de 2 mil participantes capacitados.  \n\nO objetivo dos cursos elaborados e oferecidos pela AMBI é o ampliar o número de profissionais preparados para conduzir esse processo, incluindo a melhoria na comunicação para reduzir a resistência das famílias em autorizarem a retirada de órgãos de parentes com diagnóstico de morte encefálica. \n\nDe acordo com Franke, a formação também busca qualificar as diferentes etapas que antecedem uma doação, abrangendo a identificação de potenciais doadores, a determinação da morte encefálica e a manutenção clínica do potencial doador, tornando o processo mais seguro.  \n\n“Atingir mais de 2,5 mil profissionais capacitados mostra que estamos conseguindo levar conhecimento técnico para quem está na linha de frente de um processo que exige muita responsabilidade. Um diagnóstico de morte encefálica precisa seguir critérios rigorosos, assim como a manutenção do potencial doador e o diálogo com a família”, afirmou. \n\nEntre as dificuldades para os familiares aceitarem autorizar os transplantes estão a compreensão ou aceitação do diagnóstico de morte encefálica, crenças religiosas, receio de alteração da integridade do corpo, desconfiança em relação ao processo e desconhecimento sobre a vontade manifestada em vida pelo familiar, ou até mesmo a percepção de que os profissionais estavam mais interessados nos órgãos do que no paciente ou em seus familiares.  \n\n“As famílias têm receio de deformação do corpo e nós explicamos adequadamente como é feito o procedimento e a reconstituição do corpo, que não deixarão deformidades visíveis nos ritos funerais como o velório. Elas trazem isso com muita clareza e nós precisamos explicar isso com tempo e clareza”, explicou. \n\nDe acordo com a AMIB, entre os participantes capacitados até agosto, estão 933 médicos, dos quais 473 receberam treinamento voltado à determinação de morte encefálica. O restante dos participantes, que são médicos, enfermeiros, psicólogos, assistentes sociais, técnicos de enfermagem, fisioterapeutas,  administradores, farmacêuticos, odontólogos, biólogos, e um nutricionista e um pedagogo, tiveram instruções sobre o Gerenciamento no processo de Doação e Transplante (GPDT) e uso da Comunicação em Situações Críticas (CSC).  \n\nAté agosto, já haviam sido realizados 73 cursos, distribuídos em 23 módulos e com atividades em 25 estados brasileiros. Ainda estão previstos mais oito treinamentos até o encerramento do projeto. Neste mês, eles ocorrerão em Fortaleza (CE) e Florianópolis (SC). \n\nTransplantes no Brasil  \n\nDe acordo com dados do Registro Brasileiro de Transplantes, da Associação Brasileira de Transplante de Órgãos (ABTO), em 2025, foram registrados 15.940 potenciais doadores no país. Desse total, 4.335 tornaram-se doadores efetivos. Entre as famílias entrevistadas, 4.200 não autorizaram a doação, o equivalente a 45% das entrevistas realizadas. No mesmo ano, o Brasil alcançou 20,3 doadores efetivos por milhão de habitantes, contra 19,2 em 2024.  ','Flávia Albuquerque - Repórter da Agência Brasil','https://www.ebc.com.br/termos-de-uso-e-condicoes-gerais-do-portal-da-ebc','Cerca de 45% das famílias entrevistadas sobre doação de órgãos recusam a autorização, segundo os dados citados na reportagem. O presidente da Associação de Medicina Intensiva Brasileira, Cristiano Franke, aponta que essa decisão pode ser influenciada pela forma como os hospitais acolhem os parentes e explicam o diagnóstico e os procedimentos.\n\nEntre setembro de 2025 e agosto de 2026, uma parceria da associação com o Ministério da Saúde capacitou 2.534 profissionais, superando a meta inicial de dois mil. Os cursos abordam identificação de potenciais doadores, morte encefálica, cuidados clínicos e comunicação em situações críticas.\n\nO texto destaca receios das famílias sobre o corpo, dúvidas quanto ao processo e desconhecimento da vontade do parente. Em 2025, o país registrou 15.940 potenciais doadores e 4.335 doações efetivas, mostrando a diferença entre a identificação dos casos e a concretização da doação.','full','https://agenciabrasil.ebc.com.br/saude/noticia/2026-09/taxa-media-de-recusa-de-doacao-de-orgaos-pelos-familiares-e-45');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('530','95d410cdafc8037597e0bf07b3dceecbd77437a67a90341e3394b8d40fa9e119','agenciabrasil','Agência Brasil','Brasil','Após frente fria, temperaturas voltam a subir nesta terça-feira (8)','Após a passagem de uma forte frente fria para esta época do ano, que derrubou as temperaturas e provocaram instabilidades no fim de semana e no feriado, a terça-feira (8) será marcada pela elevação gradual dos termômetros no Centro-Oeste e pela redistribuição…','https://agenciabrasil.ebc.com.br/meio-ambiente/noticia/2026-09/apos-frente-fria-temperaturas-voltam-subir-nesta-terca-feira','','2026-09-08 07:00:00','Após a passagem de uma forte frente fria para esta época do ano, que derrubou as temperaturas e provocaram instabilidades no fim de semana e no feriado, a terça-feira (8) será marcada pela elevação gradual dos termômetros no Centro-Oeste e pela redistribuição das chuvas pelas demais regiões do país.\n\nCentro-Oeste\n\nNo Centro-Oeste, de acordo com o Instituto Nacional de Meteorologia (Inmet), pancadas de chuva com trovoadas isoladas ainda estão previstas para o norte, leste e sudeste de Mato Grosso, além de grande parte de Goiás. No Distrito Federal e nas demais áreas do MT ocorrem chuvas isoladas.\n\nNotícias relacionadas:\n\nEspecialistas defendem protagonismo indígena na restauração de terras.\n\nSenado aprova direito prioritário da criança a meio ambiente saudável.\n\nSeca na Amazônia atingiu 38% das áreas habitadas no último El Niño.\n\nApós o frio do feriadão, as temperaturas entram em elevação na região. A mínima será de 17 °C em Campo Grande (MS) e a máxima chega a 35 °C em Cuiabá (MT). A temperatura segue amena no Distrito Federal, com máxima de 27 °C em Brasília.\n\nSul\n\nEm grande parte da Região Sul será mais um dia de sol e poucas nuvens, com o frio começando a diminuir. No Paraná, a nebulosidade aumenta. Em Santa Catarina e no Rio Grande do Sul, o predomínio será de poucas nuvens e temperaturas baixas.\n\nHá previsão de geada durante a madrugada e ao amanhecer no centro-leste do Rio Grande do Sul e nas serras de Santa Catarina. Entre as capitais, a mínima será de 8 °C em Curitiba (PR) e a máxima de 22 °C em Porto Alegre (RS).\n\nSudeste\n\nA volta do feriadão no Sudeste terá pancadas de chuva e trovoadas isoladas no Triângulo Mineiro. Chuvas isoladas ocorrem no centro-norte de Minas Gerais e do Espírito Santo. Nas demais áreas da região, o céu fica com muitas nuvens e possibilidade de chuva isolada.\n\nO frio começa a diminuir no Sudeste. Entre as capitais, a mínima será de 11 °C em São Paulo. As máximas voltam a superar a marca dos 20 °C em todas as capitais, chegando a 25 °C no Rio de Janeiro (RJ).\n\nNorte\n\nNo Norte, a terça-feira segue com instabilidades sobre grande parte dos estados do Amazonas, Tocantins e no sudeste do Pará, onde ocorrem pancadas de chuva com trovoadas isoladas. Há possibilidade de chuvas isoladas em outras localidades e tempo com muitas nuvens no norte do Pará e no Amapá. Em relação às temperaturas, a mínima será de 20 °C em Rio Branco (AC), e a máxima, de 36 °C em Rio Branco, Manaus (AM) e Palmas (TO).\n\nNordeste\n\nJá no Nordeste, as condições para pancadas de chuva isoladas persistem sobre o centro-sul e oeste da Bahia, no sul e noroeste do Maranhão. Também há possibilidade de chuvas isoladas no centro-sul do Piauí e do Maranhão e na faixa litorânea da região Nordeste. Nas demais áreas, o dia terá muitas nuvens, mas sem chuva.\n\nEntre as capitais, a temperatura mínima será de 23 °C em Aracaju (SE) e Maceió (AL), e a máxima chega a 33 °C em São Luís (MA) e 39 °C em Teresina (PI).','Agência Brasil','https://www.ebc.com.br/termos-de-uso-e-condicoes-gerais-do-portal-da-ebc','Após uma frente fria que reduziu as temperaturas no fim de semana e no feriado, a previsão de 8 de setembro indica aquecimento gradual no Centro-Oeste.','excerpt','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('531','736d7d76560800b91a0ddd9d26eeb52d16b53d1ecf42f8e243ab7af6867452fd','agenciabrasil','Agência Brasil','Esportes','Vitória se afasta do Z-4 e mantém Grêmio ameaçado no Brasileirão','Em confronto direto para se distanciar da zona de rebaixamento do Campeonato Brasileiro, o Vitória levou a melhor sobre o Grêmio. Na noite dessa segunda-feira (7), o Leão rubro-negro superou o Tricolor gaúcho por 1 a 0 no Barradão, em Salvador, na partida que…','https://agenciabrasil.ebc.com.br/esportes/noticia/2026-09/vitoria-se-afasta-do-z-4-e-mantem-gremio-ameacado-no-brasileirao','','2026-09-08 06:45:00','','Lincoln Chaves - Repórter da EBC','','O Vitória venceu o Grêmio por 1 a 0 no Barradão e terminou a 26ª rodada do Brasileirão em 11º lugar, com 32 pontos. O resultado interrompeu uma sequência de duas derrotas e ampliou a distância do time baiano para a zona de rebaixamento.\n\nRenê marcou de cabeça no segundo tempo após uma cobrança de escanteio de Mateus Silva. Antes disso, o Grêmio chegou a balançar a rede com Carlos Vinícius, mas o lance foi anulado por impedimento. Weverton também preocupou a equipe ao cair no gramado antes do início, porém se recuperou e participou do jogo.\n\nSem conseguir reagir ao gol, o Grêmio permaneceu em 15º, com 28 pontos, três acima do Vasco, que abria o Z-4. O time gaúcho seguia sem vitórias como visitante no campeonato.','article','https://agenciabrasil.ebc.com.br/esportes/noticia/2026-09/vitoria-se-afasta-do-z-4-e-mantem-gremio-ameacado-no-brasileirao');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('532','a98bde60db695639eacd268441c8ef23387b87afec27b86ddd1dac8a50e6836c','agenciabrasil','Agência Brasil','Educação','Pisa: Brasil reduz diferença para países ricos no desempenho escolar','A educação brasileira segue com desempenho muito inferior ao de países desenvolvidos, mas a diferença caiu ao longo das últimas duas décadas. É o que apontam os mais recentes resultados do Programa Internacional de Avaliação de Estudantes (Pisa), referente ao…','https://agenciabrasil.ebc.com.br/educacao/noticia/2026-09/pisa-brasil-reduz-diferenca-para-paises-ricos-no-desempenho-escolar','','2026-09-08 06:30:00','A educação brasileira segue com desempenho muito inferior ao de países desenvolvidos, mas a diferença caiu ao longo das últimas duas décadas. É o que apontam os mais recentes resultados do Programa Internacional de Avaliação de Estudantes (Pisa), referente ao ano de 2025, divulgados nesta terça-feira (8) pela Organização para a Cooperação e Desenvolvimento Econômico (OCDE). Aplicado a cada três anos pela entidade, o Pisa avalia os conhecimentos de estudantes na faixa de 15 anos de idade em matemática, leitura e ciências.\n\nCom os resultados de 2025, que se mantiveram estáveis em relação a 2022, o Brasil segue no grupo abaixo da média dos países da OCDE nas três disciplinas. Foram 408 pontos em leitura, 377 em matemática e 409 em ciências. Nesta mesma ordem, a média de 23 países da OCDE ficou em 466 (leitura), 469 (matemática) e 486 (ciências). Cada 20 pontos equivalem a um ano escolar. Em matemática, por exemplo, o Brasil está com cerca de 4,6 anos de atraso em relação aos membros da OCDE.\n\nNotícias relacionadas:\n\nPisa: meninas vão melhor em leitura e meninos, em matemática.\n\nPisa mostra que 2% dos alunos brasileiros têm nota máxima .\n\nUso excessivo de dispositivo digital afeta desempenho de alunos.\n\nA distância, no entanto, já foi bem maior, quando se comparam os dados entre os anos de 2006 e 2025. A diferença de desempenho em relação à média dos países da OCDE diminuiu de 102 para 58 em leitura (redução de 44 pontos), de 131 para 92 em Matemática (39 pontos) e de 113 para 77 em Ciências (36 pontos).\n\nO estudo do ano passado envolveu 760 mil estudantes de 91 países. O Brasil participou da pesquisa com 30.140 estudantes. O perfil dos participantes brasileiros avaliados foi composto por 72,4% de estudantes oriundos de escolas da rede estadual, sendo a quase totalidade (96,9%) delas localizada em áreas urbanas. Cerca de 84,7% estavam matriculados na 1ª ou 2ª série do Ensino Médio na época das provas, aplicadas entre abril e maio de 2025. Nesta edição, o foco foi o letramento dos alunos em ciências, com o maior número de itens aplicados. Foi em ciências, aliás, que a nota do Brasil mais evoluiu na comparação com o ciclo anterior de avaliação (2022), saltando de 403 para 409 pontos.\n\nO Pisa 2025 também aponta melhor recuperação do Brasil após a pandemia de covid-19 do que a média da OCDE. Entre 2018 e 2025, o país recuperou e superou o desempenho pré-pandemia em ciências e registrou perdas menores que a média da OCDE em Leitura e Matemática. No Brasil, a avaliação é aplicada pelo Instituto Nacional de Estudos e Pesquisas Educacionais Anísio Teixeira (Inep), autarquia vinculada ao Ministério da Educação (MEC).\n\nFerramentas computacionais\n\nO ano de 2025 marca o nono ciclo da avaliação do Pisa desde seu lançamento, em 2000, ano em que o Brasil aderiu ao programa, participando de todas as avaliações desde então. Nesta edição, como é praxe, o Pisa introduziu um novo domínio. A dimensão escolhida foi \"Aprendizagem no Mundo Digital\", que envolveu dois atributos: a Resolução de Problemas por meio de Ferramentas Computacionais (RPFC) e Processos de Aprendizagem Autorregulada.\n\nA pandemia revelou a desigualdade de acesso à internet - Caminhos da Reportagem/TV Brasil\n\nNa divulgação do primeiro volume de resultados, a OCDE disponibilizou as médias e os níveis de proficiência no atributo de RPFC. Já os resultados sobre o construto de Processos de Aprendizagem Autorregulada serão disponibilizados em 2027.\n\nEm RPFC, o Brasil ficou com 406 pontos, abaixo da média da OCDE (500). Entre os 19 países selecionados, a Coreia do Sul apresentou a maior média (538), enquanto o Paraguai apresentou a menor (352).\n\nCelulares nas escolas\n\nNa avaliação do Pisa em 2025, os estudantes também respondem a questionários contextuais, incluindo sobre o uso de celulares em sala de aula. O resultado mostrou que 81% dos estudantes brasileiros avaliados frequentavam escolas com restrições ao uso desses dispositivos. Em 2022, eram 37%. A proporção brasileira supera amplamente a média da OCDE (49%).\n\n Celular nas escolas -  Foto: Fabio Rodrigues-Pozzebom/ Agência Brasil\n\nSegundo o MEC, o percentual medido está alinhado às evidências de que estudantes em escolas com esse tipo de regra apresentam menor probabilidade de relatar distrações digitais. \"O resultado também reflete a implementação da Lei nº 15.100/2025, que estabeleceu regras para o uso de celulares na educação básica em todo o país\", observou a pasta, em nota.\n\nNo relatório anterior, de 2022, a OCDE havia apontado que o uso excessivo de dispositivo digital afeta desempenho de alunos em todos os países analisados.\n\nCuriosidade e perseverança\n\nEm 2025, 72% dos estudantes brasileiros afirmaram ter interesse por diversos assuntos, ao passo que 59% disseram se esforçar mais diante de desafios. Ao mesmo tempo, caiu para 16% a parcela que considera a escola uma perda de tempo, percentual significativamente inferior à média da OCDE (24%) e 6,9 pontos menor que em 2022.\n\nOs dados também mostram que a valorização da escola faz diferença na aprendizagem. No Brasil, estudantes que reconhecem o valor da educação e rejeitam a ideia de que a escola é uma perda de tempo obtêm, em média, 35 pontos a mais em ciências do que seus colegas, impacto superior ao observado na média da OCDE (27 pontos).\n\nMeio ambiente\n\nResultados do Pisa 2025 mostram também que os estudantes brasileiros estão entre os mais engajados com as questões ambientais. No Brasil, 84% acreditam que podem gerar impactos positivos para o meio ambiente, 87% confiam na força da  ação coletiva para enfrentar desafios ambientais e 77% afirmam saber trabalhar em grupo para promover mudanças positivas. São percentuais superiores aos observados na média da OCDE, destacou o MEC.\n\nEntenda o Pisa\n\nCoordenado pela OCDE, o Pisa é uma avaliação internacional aplicada a cada três anos a estudantes de 15 anos. É considerado o maior estudo sobre educação no mundo e avalia até que ponto os estudantes dessa idade, próximos ao que se considera o final da escolaridade obrigatória na maioria dos países (equivalente ao Ensino Médio), adquiriram conhecimentos e habilidades essenciais para plena participação na vida social e econômica.\n\nO exame procura medir a capacidade dos jovens de aplicar conhecimentos de matemática, leitura e ciências em situações da vida real e permite comparar o desempenho dos sistemas educacionais de diferentes países. A cada edição, uma dessas três áreas recebe maior ênfase. No Pisa 2025, o foco principal foi ciências, além da introdução de uma avaliação de língua estrangeira e de um novo domínio sobre aprendizagem no mundo digital.\n\nNo Brasil, a aplicação é coordenada pelo Inep, que seleciona as escolas participantes, organiza a aplicação e analisa os dados. O Brasil participa do Pisa desde 2000. O exame é amostral e não corresponde a uma prova aplicada a todos os estudantes de 15 anos. O ciclo mais recente foi realizado em 2025, depois de o calendário ter sido alterado pela pandemia de covid-19: a edição prevista para 2021 foi realizada em 2022, e a que estava prevista para 2024 foi transferida para 2025.\n\nA OCDE é uma organização internacional que reúne 38 países, incluindo algumas das maiores economias do planeta, para produzir estudos, estatísticas e recomendações sobre políticas públicas e desenvolvimento econômico e social. O Brasil, embora não seja membro, participa de programas da entidade, como o Pisa. Em 2022, o país recebeu o convite formal para iniciar o processo de adesão, mas a entrada depende do cumprimento de uma série de requisitos e da aprovação dos países membros.','Pedro Rafael Vilela - Repórter da Agência Brasil','https://www.ebc.com.br/termos-de-uso-e-condicoes-gerais-do-portal-da-ebc','O Brasil segue abaixo da média da OCDE em leitura, matemática e ciências, mas reduziu a distância em relação aos países desenvolvidos nas últimas duas décadas. No Pisa de 2025, as notas brasileiras foram 408, 377 e 409 pontos nessas áreas, respectivamente, segundo os resultados apresentados pela Agência Brasil.\n\nA melhora em relação a 2006 não elimina a defasagem: em matemática, a diferença para a média citada equivale a aproximadamente 4,6 anos escolares. Em comparação com 2022, os resultados ficaram relativamente estáveis, com avanço mais perceptível em ciências.\n\nO levantamento também mostra maior presença de restrições ao celular nas escolas frequentadas pelos participantes brasileiros: de 37% em 2022 para 81% em 2025. A edição avaliou cerca de 30 mil estudantes do país e incluiu habilidades de aprendizagem digital, nas quais o desempenho brasileiro também ficou abaixo da média da OCDE.','full','https://agenciabrasil.ebc.com.br/educacao/noticia/2026-09/pisa-brasil-reduz-diferenca-para-paises-ricos-no-desempenho-escolar');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('543','f6250a1bc628586e09d82b2de34778e607f20845fb5c501d62676aab30d3bcf3','agenciabrasil','Agência Brasil','Brasil','PF mira grupo suspeito de desviar encomendas postais','A Polícia Federal (PF) cumpre três mandados de prisão preventiva nesta quarta-feira (9), contra suspeitos de furtar encomendas enviadas pelos correios, por meio do uso de documentos falsificados. Também estão sendo cumpridos oito mandados de busca e apreensão…','https://agenciabrasil.ebc.com.br/geral/noticia/2026-09/pf-mira-grupo-suspeito-de-desviar-encomendas-postais','','2026-09-09 09:57:00','A Polícia Federal (PF) cumpre três mandados de prisão preventiva nesta quarta-feira (9), contra suspeitos de furtar encomendas enviadas pelos correios, por meio do uso de documentos falsificados. Também estão sendo cumpridos oito mandados de busca e apreensão.\n\nOs policiais cumprem os mandados na zona oeste da cidade do Rio de Janeiro e no município de São Vicente, em São Paulo.\n\nNotícias relacionadas:\n\nPF faz ação contra apologia ao nazismo no interior do Rio de Janeiro.\n\nPolícia faz operação contra venda de medicamentos abortivos no Rio.\n\nAs investigações começaram em 2024, depois que uma mulher foi presa em flagrante enquanto retirava uma encomenda postal usando documentos falsos da verdadeira destinatária.\n\nSegundo a PF, o esquema é parte de uma estrutura criminosa que monitora objetos de alto valor econômico, confecciona os documentos falsos e faz retiradas fraudulentas em diversas unidades dos Correios, nos estados do Rio e de São Paulo.\n\nPelo menos 24 ações criminosas foram monitoradas pela PF, entre elas retiradas tentadas e consumadas, desses objetos postais.\n\nOs investigados poderão responder pelos crimes de furto qualificado mediante fraude e organização criminosa, sem prejuízo da apuração de outros delitos eventualmente identificados no decorrer das diligências.','Vitor Abdala - Repórter da Agência Brasil','https://www.ebc.com.br/termos-de-uso-e-condicoes-gerais-do-portal-da-ebc',NULL,'','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('544','323c826d275e957a11a79006edd1d638b4042becbcc82e5e1677c2d3f1c30aea','agenciabrasil','Agência Brasil','Brasil','Anvisa amplia indicação de vacina contra meningite ','A Agência Nacional de Vigilância Sanitária (Anvisa) aprovou a ampliação da indicação da vacina MenQuadfi para crianças a partir de 6 semanas de idade. A decisão permite que o imunizante seja usado tanto em adultos quanto em crianças para a prevenção da doença…','https://agenciabrasil.ebc.com.br/saude/noticia/2026-09/anvisa-amplia-indicacao-de-vacina-contra-meningite','','2026-09-09 09:54:00','','Brasília','',NULL,'','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('545','f6107493f61a06aff3fe5f0cb312910b2418144b563b38bf8edaf520a4b1356f','agenciabrasil','Agência Brasil','Educação','Feira em SP reúne programas de intercâmbio e bolsas esportivas','A cidade de São Paulo recebe neste sábado (12) a Feira de Educação Internacional da CI, um evento com entrada gratuita que destaca oportunidades de intercâmbio para ensino médio no exterior, graduação, pós-graduação e MBA. A feira reunirá mais de 40 expositor…','https://agenciabrasil.ebc.com.br/educacao/noticia/2026-09/feira-em-sp-reune-programas-de-intercambio-e-bolsas-esportivas','','2026-09-09 09:45:00','A cidade de São Paulo recebe neste sábado (12) a Feira de Educação Internacional da CI, um evento com entrada gratuita que destaca oportunidades de intercâmbio para ensino médio no exterior, graduação, pós-graduação e MBA.\n\nA feira reunirá mais de 40 expositores com oportunidades de intercâmbio e consultorias especializadas para países como Inglaterra, Irlanda, Austrália, Nova Zelândia, Itália e Emirados Árabes Unidos.\n\nO grande destaque do evento são as bolsas esportivas, que permitem que esportistas cursem o ensino médio em países como Estados Unidos, Canadá, Espanha e Portugal.\n\nDestinadas a estudantes de 14 a 17 anos que desejam conciliar os estudos com a rotina de competições, as bolsas concedem um ano acadêmico em instituições dos Estados Unidos, Canadá, Espanha ou Portugal.\n\nAs modalidades contempladas pelo programa são futebol, basquete, vôlei, beisebol, natação e tênis, sendo que as bolsas de futebol são exclusivas para estudo na Espanha e Portugal.\n\nPara concorrer, os candidatos devem apresentar bom desempenho escolar, conhecimento intermediário de inglês e comprovar a prática do esporte por meio de fotos e vídeos.\n\nO processo seletivo compreende uma avaliação de proficiência no idioma inglês, preenchimento da ficha de inscrição e entrevista online com treinadores. A taxa de aplicação exigida será isenta para quem se inscrever durante a feira, e o resultado final é divulgado em até 30 dias.\n\nO benefício anual concedido aos aprovados varia entre US$ 20 mil e US$ 50 mil, cobrindo a moradia no campus da escola e a alimentação ao longo do período. Custos pessoais, como emissão de passaporte, taxa de visto, passagens aéreas, seguro-saúde, uniforme e material escolar, não estão inclusos na bolsa.\n\nAlém de consultoria, os visitantes podem conhecer cursos de idiomas e participar de palestras, orientações personalizadas e promoções exclusivas.\n\nNos próximos finais de semana do mês de setembro, o evento passará por Campo Grande (15), Brasília (17) e Goiânia (19). É necessário fazer a inscrição no site oficial do evento para participar da feira, mas também será possível acompanhar o evento de forma online, através de transmissões ao vivo no YouTube.\n\nO evento acontece no Tivoli Mofarrej São Paulo Hotel, localizado na Alameda Santos, 1437, Cerqueira César.\n\n*Estagiário da Agência Brasil sob supervisão de Odair Braz Junior','Matheus Crobelatti* – Agência Brasil','https://www.ebc.com.br/termos-de-uso-e-condicoes-gerais-do-portal-da-ebc',NULL,'','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('546','94cacf1b9b1e8b98a8edfea81e1270167f01fae87c692d444a9839f841ff769b','agenciabrasil','Agência Brasil','Brasil','Dino determina reintegração de Andrei Rodrigues no comando da PF','O ministro Flávio Dino, do Supremo Tribunal Federal (STF), determinou nesta quarta-feira (9) a reintegração de Andrei Rodrigues como diretor-geral da Polícia Federal (PF). O delegado foi afastado do cargo na terça-feira (8) por decisão do também ministro Andr…','https://agenciabrasil.ebc.com.br/justica/noticia/2026-09/dino-determina-reintegracao-de-andrei-rodrigues-no-comando-da-pf','','2026-09-09 09:25:00','O ministro Flávio Dino, do Supremo Tribunal Federal (STF), determinou nesta quarta-feira (9) a reintegração de Andrei Rodrigues como diretor-geral da Polícia Federal (PF). \n\nO delegado foi afastado do cargo na terça-feira (8) por decisão do também ministro André Mendonça. A maioria dos ministros da Segunda Turma do STF acompanhou a decisão de Mendonça, mas o julgamento foi interrompido após pedido de vista do ministro Gilmar Mendes.\n\nNotícias relacionadas:\n\nDiretores da PF apoiam Andrei Rodrigues e colocam cargos à disposição.\n\n\"Verdade prevalecerá\", diz número 2 da PF após afastamento de Andrei .\n\nDino atendeu a pedido formulado pelo próprio Andrei Rorigues. Em sua determinação, Dino mencionou “atropelos processuais” para afirmar a nulidade do afastamento, entre os quais ilegitimidade do partido Novo para pedir o afastamento de autoridade pública em um processo de natureza criminal. \n\n“O partido político mencionado, no caso, não possui legitimidade para requerer medidas cautelares em investigações criminais ou processos penais, como revela o próprio desenho normativo do Código de Processo Penal, em cujos preceitos inexiste qualquer referência a partidos políticos entre os sujeitos legitimados a atuar nessa seara do Direito”, escreveu o ministro. \n\nDino frisou ainda que o Novo possui interesse direto e político-partidário no afastamento de Andrei Rodrigues, uma vez que possui candidato próprio à presidência da República, o ex-governador de Minas Gerais Romeu Zema, adversário do atual mandatário e candidato à reeleição, o presidente Luiz Inácio Lula da Silva, que foi quem nomeou o diretor-geral da PF. \n\n“Não há dúvida de que tal projeto eleitoral é absolutamente legítimo, em sua seara própria, mas não em um processo penal que, por sua gravidade, não pode ter as suas regras vilipendiadas.”\n\nInvestigações paralisadas\n\nO ministro mandou reintegrar também o diretor de Inteligência da PF, Leandro Almada. Ele citou o prejuízo de investigações em curso, sob sua relatoria, caso a produção de relatórios de inteligência seja interrompida. \n\n“Em área de tamanha sensibilidade institucional, a abrupta substituição da direção possui aptidão para comprometer a continuidade dos trabalhos, os fluxos de informação e o tempestivo cumprimento de determinações judiciais, de modo que, seja pelas ilegalidades já assinaladas, seja pela necessidade de preservar a regular atuação da Polícia Federal, impõe-se, neste juízo sumário, o restabelecimento de sua situação funcional”, escreveu Dino sobre Almada. \n\nA decisão de Dino foi tomada no processo em que a PF analisa o material apreendido pela Polícia Civil de São Paulo em investigações sobre o desvio de emendas parlamentares para financiar a produção do filme Dark Horse, cinebiografia do ex-presidente Jair Bolsonaro. \n\nNo pedido para ser reintegrado, Andrei Rodrigues alegou que seu afastamento “interfere na organização da equipe responsável pelas investigações, retarda o acesso ao material disponibilizado e compromete a atuação célere da instituição”.\n\nCompetência \n\nOutro argumento do ministro Dino para derrubar a decisão de Mendonça é o de que o colega não teria a competência para determinar o afastamento do diretor-geral da PF. \n\nAo afastar o diretor-geral da PF, Mendonça alegou ser alvo de “monitoramento sistemático”, de forma ilegal, por parte do setor de inteligência da PF, com a produção de ao menos seis relatórios ocultos e apócrifos durante o mês de agosto. \n\nDino destacou, contudo, que o presidente do Supremo, Edson Fachin, já abriu, no último dia 3 de setembro, um processo para apurar os relatórios das quais Mendonça é alvo, motivo pelo qual o ministro não poderia ter proferido uma decisão tendo como base os mesmos documento. \n\nUma vez que a controvérsia encontra-se sob relatoria do Fachin, apenas o presidente dado Supremo ou o plenário teria competência para tomar decisões com base na regularidade ou não de tais relatórios. \n\n“Ou seja, caso o Exmo. Ministro André Mendonça, parte no procedimento instaurado pelo Presidente, considere que há um direito subjetivo em risco, é ao Presidente ou ao Plenário que deve se dirigir, sob pena de grave usurpação das atribuições dos demais Ministros”, afirmou Dino. \n\nO ministro determinou que somente o plenário possa julgar sua decisão de reintegrar Andrei Rodrigues. Dino acrescentou ainda que, ao afastar o diretor-geral da PF, Mendonça teria agido em causa própria. \n\n“Compreende-se que o digno Ministro André Mendonça tenha suas divergências funcionais ou pessoais com a Polícia Federal e possa defender os seus direitos perante a instância própria. Mas tais direitos — inerentes a qualquer parte que se sinta prejudicada — não podem converter-se em fundamento para a prolação de decisão em causa própria, com o efeito de paralisar investigações e os trabalhos policiais”. \n\nRecursos\n\nAo determinar o afastamento de Andrei Rodrigues, o ministro André Mendonça submeteu sua decisão para referendo da Segunda Turma do STF, horas depois depois de assinar o despacho, em sessão extraordinária de 24 horas. \n\nA Segunda Turma alcançou maioria de três votos entre os cinco ministros que compõem o colegiado para manter o afastamento, com os votos dos ministros Luiz Fux e Nunes Marques favoráveis à decisão de Mendonça. O julgamento não foi concluído, contudo, devido a um pedido de vista (mais tempo de análise) do ministro Gilmar Mendes. \n\nAinda ontem, a Advocacia-Geral da União (AGU) pediu a Fachin, presidente do Supremo, a suspensão da liminar de Mendonça, alegando usurpação de prerrogativa exclusiva do presidente da República para nomear e exonerar a chefia da PF. \n\nAinda na noite de terça, Fachin abriu prazo de três dias para Mendonça responder o recurso da AGU. Tal prazo, contudo, acabou atropelado pela decisão de Dino. \n\nEm paralelo, Fachin é relator de um processo em que a regularidade ou não dos relatórios citados por Mendonça é analisada. O presidente do Supremo pediu manifestação dos envolvidos e ainda não decidiu se abre ou não uma investigação sobre os documentos. \n\nMaster\n\nA crise entre ministros do Supremo ganhou proporções sem precedentes depois de Mendonça ter divulgado, na semana passada, relatórios parciais da Operação Compliance Zero, da qual é relator e que tem como alvo a corrupção de agentes públicos e fraudes financeiras bilionárias supostamente praticadas pelo ex-banqueiro Daniel Vorcaro, antigo dono do Banco Master. \n\nNo material divulgado constam 52 mensagens que os investigadores do caso dizem terem sido enviadas por Vorcaro a Moraes. Nelas, o ex-banqueiro demonstra proximidade com o ministro e aparenta ter encaminhado a ele um contrato de R$ 131 milhões entre o Master e o escritório de advocacia de Viviane Barci de Moraes, esposa do ministro. \n\nEm outro trecho, Vorcaro parece buscar junto a Moraes informações sobre uma possível operação da PF para prendê-lo. As respostas do interlocutor ao ex-banqueiro não puderam ser resgatadas, informaram os investigadores. \n\nLogo após a divulgação do material, Moraes decidiu tornar público o que disse ser um \"relatório de inteligência\" da PF segundo o qual Mendonça estaria direcionando as investigações do caso Master contra desafetos políticos.\n\nO documento, porém, não é assinado nem traz o cabeçalho da corporação, além de trazer capa o alerta de que seu conteúdo foi produzido \"sem caráter probatório\". \n\nAmpliada às 10h38','Felipe Pontes – repórter da Agência Brasil','https://www.ebc.com.br/termos-de-uso-e-condicoes-gerais-do-portal-da-ebc',NULL,'','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('547','8260d5e4e4634a31bd53c43183d8b5f4da7621209ba1988cf49ddda587457a2f','agenciabrasil','Agência Brasil','Brasil','Comissão da Verdade Indígena será tema de audiência na Câmara','Demanda de mais de uma década dos povos originários, a criação da Comissão Nacional Indígena da Verdade (CNIV) será pauta no Congresso Nacional, por iniciativa da ex-ministra e deputada federal Sônia Guajajara (PSOL-SP). A parlamentar organizou uma audiência …','https://agenciabrasil.ebc.com.br/politica/noticia/2026-09/comissao-da-verdade-indigena-sera-tema-de-audiencia-na-camara','','2026-09-09 08:45:00','Demanda de mais de uma década dos povos originários, a criação da Comissão Nacional Indígena da Verdade (CNIV) será pauta no Congresso Nacional, por iniciativa da ex-ministra e deputada federal Sônia Guajajara (PSOL-SP). A parlamentar organizou uma audiência pública para 17 de novembro na Câmara dos Deputados, com o objetivo de avançar na proposta.\n\nA audiência foi aprovada por meio do Requerimento nº 86/2026 na Comissão da Amazônia e dos Povos Originários e Tradicionais. O documento destaca a Articulação dos Povos Indígenas do Brasil (Apib) como uma das entidades que vêm reiterando a necessidade de se captar, com a formação da CNIV, mais elementos que comprovem ações de despotismo durante a ditadura militar.\n\nNotícias relacionadas:\n\nOrganizações cobram criação de Comissão da Verdade Indígena.\n\nNo Dia dos Povos Indígenas, organizações cobram demarcações e proteção.\n\nAo criar a CNIV, o objetivo é responsabilizar o Estado pelas violências que cometeu, que assumiram a forma de escravização, estupros, envenenamentos, torturas, remoções dos indígenas de seus territórios, entre outras. Houve ainda pessoas desaparecidas e presas ilegalmente e com bens culturais destruídos. \n\nDevem comparecer à audiência, além de lideranças indígenas, representantes do poder público, do sistema de Justiça, da sociedade civil e pesquisadores. Eles devem apresentar contribuições, ampliando a documentação feita pela Comissão Nacional da Verdade (CNV), que é reconhecida pelo movimento indígena mas insuficiente, por conter descrições dos impactos na vida de dez povos apenas. \n\nAs populações dos Tapayuna, Parakanã, Araweté, Arara, Panará, Waimiri-atroari, Cinta-larga, Xetá, Yanomami e Xavante equivaliam, somadas, a 3,3% dos povos identificados na época. O levantamento permitiu que se chegasse a uma estimativa de 8.350 indígenas assassinados entre 1964 e 1985. A contagem oficial do Brasil relaciona 305 povos, número que aumenta com os classificados como em isolamento e é provavelmente inferior à quantidade real.\n\nEliminados \n\nUm dos não indígenas mais incansáveis nessa luta, o jornalista Marcelo Zelic, que morreu em maio de 2023 em decorrência de um AVC, era integrante do Grupo de Trabalho (GT) Indígena da CNV e questionou o relatório concluído em 2014. A primeira versão tinha somente 35 páginas, quase o total de unidades federativas do Brasil. Era como se em uma página pudessem ser resumidos todos os crimes ocorridos em 21 anos de ditadura, caso dedicassem uma página por estado. \n\n Após protestos do GT e a manifestação de descontentamento de Zelic com a qualidade do relatório, na 29ª Reunião Brasileira de Antropologia (RBA), o material foi substituído.\n\nAo questionar as autoridades sobre as versões do documento, Marcelo Zelic apresentou o texto \"Comissão Nacional da Verdade e Povos Indígenas: a um passo da omissão\" para expressar sua indignação com a síntese, que considerou curta demais. Ele afirma que o Estado facilitou a prática das violências e que isso fica evidente quando se descobre que muitas eram perpetradas por funcionários do Serviço de Proteção aos Índios (SPI), ativo de 1910 a 1967, e que foi sucedido pela Fundação Nacional do Índio (Funai). \n\n\"Os povos indígenas foram um dos grupos sociais mais violados em seus direitos no período de apuração da CNV (1946-1988), crimes bárbaros foram praticados em todas as décadas em questão, por ação, conivência, corrupção e omissão do Estado brasileiro, diz no texto. Ele citou o Relatório Figueiredo e fundou e coordenou o projeto Armazém Memória.\n\nNo texto, Zelic sugere que a comissão deveria contar com uma coordenação-geral e uma equipe técnica para auxiliar nos trabalhos e por um colegiado de comissionados, composto por órgãos do Estado, representações dos povos indígenas e entidades da sociedade civil de caráter indigenista e de direitos humanos, responsáveis pela estruturação da Rede de Comissões da Verdade Indígena (Rede CVI). Assim, casos concluídos pela Rede CVI seriam enviados ao colegiado para a abertura de processos. \n\nUma condição para sustentar esse fluxo seria estimular os povos originários a criarem comissões para si e em universidades que possam colaborar com levantamentos. Outra finalidade diz respeito à mensuração de impactos territoriais, sociais, culturais e espirituais na vida das comunidades.\n\n“Não podemos construir uma democracia verdadeira sem reconhecer as violências cometidas contra os povos indígenas. Precisamos garantir o direito à memória e à verdade, identificar responsabilidades e construir políticas de reparação integral para que essas violações nunca mais se repitam”, afirma Sônia Guajajara.','Letycia Treitero Kawada - Repórter da Agência Brasil','https://www.ebc.com.br/termos-de-uso-e-condicoes-gerais-do-portal-da-ebc',NULL,'','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('548','f1e5db1de2b54797c3f47842d227bf2e2541cc333b24bf662d8aa24f2e7c1e8d','agenciabrasil','Agência Brasil','Brasil','PF faz ação contra apologia ao nazismo no interior do Rio de Janeiro','Policiais federais fizeram, nesta quarta-feira (9), uma ação contra suspeitos da prática do crime de apologia ao nazismo, em Valença, no sul do estado do Rio de Janeiro. Foram expedidos dois mandados de busca e apreensão pela Justiça Federal. Notícias relacio…','https://agenciabrasil.ebc.com.br/geral/noticia/2026-09/pf-faz-acao-contra-apologia-ao-nazismo-no-interior-do-rio-de-janeiro','','2026-09-09 08:40:00','Policiais federais fizeram, nesta quarta-feira (9), uma ação contra suspeitos da prática do crime de apologia ao nazismo, em Valença, no sul do estado do Rio de Janeiro. \n\nForam expedidos dois mandados de busca e apreensão pela Justiça Federal.\n\nNotícias relacionadas:\n\nPF faz operação para combater apologia ao nazismo na internet.\n\nSegundo a Polícia Federal (PF), a investigação começou a partir da análise de um perfil na rede social X (antigo Twitter), que publicava reiteradamente conteúdos de caráter nazista.\n\nDurante as buscas, foram apreendidos um computador e um celular que serão submetidos à perícia técnica criminal.\n\nA PF ressalta que a divulgação de conteúdo de apologia ao nazismo é conduta prevista na Lei nº 7.716/1989 (Lei que define os crimes resultantes de preconceito de cor e raça).\n\nAs penas variam de dois a cinco anos de prisão se a internet for usada para este tipo de conteúdo.','Vitor Abdala – Repórter da Agência Brasil','https://www.ebc.com.br/termos-de-uso-e-condicoes-gerais-do-portal-da-ebc',NULL,'','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('549','3a8ed0fba2f690ef0656a987696f48fb2aaf977eb304dc12406af0504b737b16','agenciabrasil','Agência Brasil','Brasil','Polícia faz operação contra venda de medicamentos abortivos no Rio','Policiais civis cumprem nesta quarta-feira (9) cinco mandados de busca e apreensão contra suspeitos de divulgar e vender ilegalmente medicamentos abortivos pela internet. De acordo com a Polícia Civil do Rio de Janeiro, as substâncias são comercializadas por …','https://agenciabrasil.ebc.com.br/geral/noticia/2026-09/policia-faz-operacao-contra-venda-de-medicamentos-abortivos-no-rio','','2026-09-09 08:34:00','Policiais civis cumprem nesta quarta-feira (9) cinco mandados de busca e apreensão contra suspeitos de divulgar e vender ilegalmente medicamentos abortivos pela internet. De acordo com a Polícia Civil do Rio de Janeiro, as substâncias são comercializadas por perfis de redes sociais e aplicativos de mensagens.\n\nA investigação apura também os crimes de falsificação, corrupção, adulteração de produtos destinados a fins terapêuticos ou medicinais, além de incitação e apologia ao crime.\n\nNotícias relacionadas:\n\nPolícia Civil recupera oito obras de Matisse roubadas em São Paulo.\n\nPolícia indicia 13 em caso de morte de homem espancado em Copacabana.\n\nSegundo a polícia, contas de redes sociais publicavam conteúdos relacionados à interrupção da gravidez, como vídeos intitulados “Como fazer um aborto seguro” e “Ajuda com positivo indesejado”. A partir daí, as pessoas interessadas eram direcionadas a canais de atendimento privado, onde o produto era vendido.\n\nO esquema usava diferentes contas, linhas telefônicas e dispositivos eletrônicos relacionados entre si, a fim de dificultar a identificação dos responsáveis pela atividade.','Vitor Abdala - Repórter da Agência Brasil','https://www.ebc.com.br/termos-de-uso-e-condicoes-gerais-do-portal-da-ebc',NULL,'','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('550','c6831e3e31669b243930672b497785d9b427de903f2ed75e63b4564b2f4084b6','agenciabrasil','Agência Brasil','Brasil','Confira a agenda dos presidenciáveis nesta quarta-feira (9)','A agenda dos presidenciáveis nesta quarta-feira (9) inclui atos e comícios, motocarreata, panfletagem e mobilização com apoiadores. Também estão previstas entrevistas e sabatinas, encontros com representantes dos setores produtivo e imobiliário, visitas a ins…','https://agenciabrasil.ebc.com.br/politica/noticia/2026-09/confira-agenda-dos-presidenciaveis-nesta-quarta-feira-9','','2026-09-09 08:16:00','A agenda dos presidenciáveis nesta quarta-feira (9) inclui atos e comícios, motocarreata, panfletagem e mobilização com apoiadores. Também estão previstas entrevistas e sabatinas, encontros com representantes dos setores produtivo e imobiliário, visitas a instituições e participação em ato contra a violência de gênero.\n\nRomeu Zema (Novo)\n\nParticipa do lançamento da Carta de Princípios aos Cristãos brasileiros, em Brasília. \n\nNotícias relacionadas:\n\nJustiça Eleitoral garante transporte e urnas adaptadas para PCD.\n\nEleições 2026: candidaturas de autistas aumentam mais de cinco vezes.\n\nWilson Grassi (Democrata) \n\nConcede entrevista ao jornal A Voz de Campos, de Campos dos Goytacazes (RJ). \n\nAugusto Cury (Avante)\n\nPela manhã, visita a 28ª Bienal Internacional do Livro de São Paulo (SP). À tarde, participa de reunião com Sindicato e Organização das Cooperativas do Estado da Bahia (Oceb) e Sindicato e Organização das Cooperativas do Estado do Paraná (Ocepar). \n\nClariana Barão (DC) \n\nÀ noite participa de evento no Jockey Club de São Paulo. \n\nFlávio Bolsonaro (PL) \n\nEm Juiz de Fora (MG), participa de motocarreata do aeroporto até o centro da cidade (cerca de 10 km). Também faz comício em trio elétrico no centro da cidade. \n\nHertz Dias (PSTU)\n\nParticipa de panfletagem no CD Leopoldina dos Correios na Vila Leopoldina, em São Paulo (SP). À tarde, participa de reunião com apoiadores do PCBR na capital paulista e concede entrevista para o podcast Meteoro Brasil. \n\nLuiz Inácio Lula da Silva (PT) \n\nParticipa do ato na Arena Carhoo, em Teresina (PI). \n\nSamara Martins (UP)\n\nParticipa do Ato Por Uma Pátria Sem Feminicídios e Sem Estupros, com concentração na Praça da Sé, em São Paulo (SP).\n\nRenan Santos (Missão)\n\nParticipa de ato com apoiadores na FGV Direito SP, em São Paulo (SP). \n\nRonaldo Caiado (PSD)\n\nParticipa de sabatina para o Jornal Itatiaia, da Rádio Itatiaia (MG), por videoconferência. Em São Paulo (SP), participa de encontro com a Associação Brasileira de Incorporadoras (Abrainc) e visita o Instituto Resgatando Vidas. Também concede entrevista para a Rádio Massa FM. \n\nOs candidatos Rui Costa Pimenta (PCO) e Edmilson Costa (PCB) não têm agenda pública de campanha nesta quarta-feira.\n\nA ordem de apresentação da cobertura da agenda dos candidatos a presidente segue rodízio diário em ordem alfabética.','Agência Brasil','https://www.ebc.com.br/termos-de-uso-e-condicoes-gerais-do-portal-da-ebc',NULL,'','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('551','1b5627945ecb5e4cfb5d227f337d876d6baf79593576e87a8f8b3a75cf965996','agenciabrasil','Agência Brasil','Brasil','Nacional estreia documentário que lembra histórico programa PRK-30','O documentário PRK-30 – O Rádio pelo Avesso estreia nos cinemas nesta quinta-feira (10), na mesma semana em que a Rádio Nacional completa 90 anos. O PRK-30 fez parte da história da emissora pública que hoje pertence à Empresa Brasil de Comunicação (EBC), send…','https://agenciabrasil.ebc.com.br/geral/noticia/2026-09/nacional-estreia-documentario-que-lembra-historico-programa-prk-30','','2026-09-09 07:58:00','','Rádio Nacional','',NULL,'','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('552','cd4125e4b5088dbc728109778c105d3bfadbcf9659ee9aac4e83e738e6251611','agenciabrasil','Agência Brasil','Brasil','Nepal: especialistas apontam necessidade de monitoramento conjunto','A continuidade das chuvas desde o desastre de 26 de agosto, nas montanhas do Nepal, mantém a região em alerta para novos deslizamentos, inundações ou avalanches, indica o Centro Internacional de Desenvolvimento Integrado de Montanhas (ICIMOD, na sigla em ingl…','https://agenciabrasil.ebc.com.br/meio-ambiente/noticia/2026-09/nepal-especialistas-apontam-necessidade-de-monitoramento-conjunto','','2026-09-09 07:52:00','','Guilherme Jeronymo- Repórter da Agência Brasil','',NULL,'','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('553','dfe72d46b18cfe7dfd16144892069d08f9254cae16452245ef5abb5cc316b3f5','g1','g1','Brasil','Dino cita impacto em investigação do filme \'Dark Horse\' ao reconduzir chefe da PF; entenda o caso','Em decisão, relator apontou que afastamento travou investigações urgentes autorizadas pelo Supremo, criticou decisão de André Mendonça e destacou a ilegitimidade do Partido Novo no processo penal.','https://g1.globo.com/politica/noticia/2026/09/09/dino-cita-impacto-em-investigacao-do-filme-dark-horse-ao-reconduzir-chefe-da-pf-entenda-o-caso.ghtml','https://s2-g1.glbimg.com/8yBZ1-IfMWTvFANUZTPRu7h4uW4=/i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2026/X/G/ellIBjQ1mI5h4wS3LyAw/jim-caviezel-jair-bolsonaro-dark-horse.jpg','2026-09-09 10:33:53','','','',NULL,'','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('554','7c6c348678da6533ff7de54404c24ce56695aaa19b5d9af8568e4a440a53fb9a','g1','g1','Brasil','Assalto com reféns termina com três suspeitos mortos em troca de tiros com a polícia em Castanhal','Quatro homens invadiram uma casa durante a madrugada. As vítimas foram resgatadas sem ferimentos e um suspeito conseguiu fugir.','https://g1.globo.com/pa/para/noticia/2026/09/09/assalto-com-refens-termina-com-tres-suspeitos-mortos-em-troca-de-tiros-com-a-policia-em-castanhal.ghtml','https://s2-g1.glbimg.com/91gqvmyMJmgUNlbvUvFG5_7VPGg=/i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2026/i/O/e25qjaSqyaHPaNY6Gvdw/captura-de-tela-2026-09-09-103426.png','2026-09-09 10:32:18','','','',NULL,'','');
INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('555','6cf1da28325fe8efed18a727c17679c34938d9d3eb12d519523c9940cc82c81e','g1','g1','Brasil','Quem foi Zélia Amador, professora emérita da UFPA e referência na luta antirracista na Amazônia','Nascida no Marajó, filha de empregada doméstica, Zélia ajudou a fundar o Centro de Estudo e Defesa do Negro do Pará, participou da articulação das cotas raciais nas universidades e levou a pauta antirracista da','https://g1.globo.com/pa/para/noticia/2026/09/09/quem-foi-zelia-amador-professora-emerita-da-ufpa-e-referencia-na-luta-antirracista-na-amazonia.ghtml','https://s2-g1.glbimg.com/ca-0lf1_qHz6ocEiiEJZzkiSfEI=/i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2018/n/J/heh4tbSM67t6vCYN2kHg/zelia-2-.jpg','2026-09-09 10:31:42','','','',NULL,'','');
