INSERT IGNORE INTO news (id,url_hash,source_key,source_name,category,title,summary,url,image_url,published_at,content_html,author,license_url,ai_summary,ai_basis,ai_reference_url) VALUES ('732','880d318f914d1fb6ba8b08670f3b5d2d5f2cc0c10244345fef369ab994a3c0c7','agenciabrasil','Agência Brasil','Brasil','Governo identifica 97 médicos falsos de IA no Youtube e aciona Google','Uma força-tarefa do governo federal identificou 97 perfis que usam Inteligência Artificial (IA) no Youtube para simular médicos e outros profissionais de saúde e disseminar informações falsas, incluindo promessas de curas e tratamentos sem comprovação científ…','https://agenciabrasil.ebc.com.br/justica/noticia/2026-09/governo-identifica-97-medicos-falsos-de-ia-no-youtube-e-aciona-google','','2026-09-09 10:18:00','Uma força-tarefa do governo federal identificou 97 perfis que usam Inteligência Artificial (IA) no Youtube para simular médicos e outros profissionais de saúde e disseminar informações falsas, incluindo promessas de curas e tratamentos sem comprovação científica.\n\nA Advocacia-Geral da União (AGU) notificou, nessa terça-feira (9), o Google, que controla o Youtube, para que remova essas contas e alerte os usuários sobre os riscos à saúde que correm ao seguir recomendações de falsos profissionais.\n\nNotícias relacionadas:\n\nAGU processa Discord e pede R$ 500 milhões por dano moral coletivo .\n\n“Os conteúdos usam avatares de aparência humana apresentados como médicos ou especialistas, atribuem qualificações profissionais fictícias e recorrem a linguagem alarmista para conferir credibilidade às informações”, diz nota do Ministério da Saúde (MS).\n\nA pasta identificou os perfis por meio do programa Saúde com Ciência, que analisa desinformação na internet relacionada à Saúde.\n\n“Parte dos perfis é direcionada especialmente à população idosa e, em alguns casos, utiliza a aparente autoridade dos personagens para promover produtos, e-books ou serviços pagos”, acrescentou o MS.\n\nA Agência Brasil procurou a assessoria do Google para uma manifestação sobre o tema, mas não obteve retorno até o fechamento desta reportagem.\n\nA notificação da AGU pede que o Youtube remova, em até 72 horas, os conteúdos identificados, ou adotem medidas de rotulagem e contextualização que deixem explícita a natureza artificial dos personagens.\n\n“A plataforma também deverá avaliar os demais canais e vídeos apontados no relatório do Ministério da Saúde à luz de suas regras sobre desinformação em saúde e conteúdo sintético, além de adotar medidas para prevenir a disseminação desse tipo de material”, explicou, em nota.\n\nAlém da pasta da Saúde, a iniciativa conta com participação da AGU, da Secretaria de Comunicação Social da Presidência da República (Secom), e dos ministérios da Justiça e Segurança Pública (MJSP) e da Ciência e Tecnologia (MCTI).','Lucas Pordeus León - Repórter da Agência Brasil','https://www.ebc.com.br/termos-de-uso-e-condicoes-gerais-do-portal-da-ebc',NULL,'','');
